PathwayData.put("data/reading_writing/units/L01U4.json",{"strand":"reading_writing","level":1,"cefr":"A1a","unit":4,"theme":"Animals Around Us","essential_question":"How do animals live and move?","schema_version":"1.0","core_words":["cat","dog","bird","fish","camel","horse","goat","rabbit","duck","run","fly","swim","jump","eat"],"recycled_words":["big","small","happy","like","favorite","eat","play","garden","school","label","title","different"],"rubrics":[{"id":"RW-RUBRIC-5T","title":"Analytic writing rubric","traits":[{"name":"Ideas","name_ar":"الأفكار","bands":[{"score":4,"descriptor":"My ideas are clear, interesting and fully developed with strong details.","descriptor_ar":"أفكاري واضحة وممتعة ومدعومة بتفاصيل قوية."},{"score":3,"descriptor":"My ideas are clear and have enough details.","descriptor_ar":"أفكاري واضحة ومعها تفاصيل كافية."},{"score":2,"descriptor":"My main idea is there but needs more details.","descriptor_ar":"فكرتي الرئيسية موجودة لكنها تحتاج إلى تفاصيل أكثر."},{"score":1,"descriptor":"My ideas are unclear or very few.","descriptor_ar":"أفكاري غير واضحة أو قليلة جدًا."}]},{"name":"Organization","name_ar":"التنظيم","bands":[{"score":4,"descriptor":"Clear beginning, middle and end; ideas flow with linking words.","descriptor_ar":"بداية ووسط ونهاية واضحة، والأفكار مترابطة بكلمات الربط."},{"score":3,"descriptor":"Clear order with some linking words.","descriptor_ar":"ترتيب واضح مع بعض كلمات الربط."},{"score":2,"descriptor":"Some order, but parts are mixed up.","descriptor_ar":"يوجد بعض الترتيب لكن بعض الأجزاء غير مرتبة."},{"score":1,"descriptor":"Ideas are not in order.","descriptor_ar":"الأفكار غير مرتبة."}]},{"name":"Vocabulary","name_ar":"المفردات","bands":[{"score":4,"descriptor":"I use exact, varied words, including new unit words, correctly.","descriptor_ar":"أستخدم كلمات دقيقة ومتنوعة، منها كلمات الوحدة الجديدة، بشكل صحيح."},{"score":3,"descriptor":"I use some new words correctly.","descriptor_ar":"أستخدم بعض الكلمات الجديدة بشكل صحيح."},{"score":2,"descriptor":"I use simple words; some are repeated or wrong.","descriptor_ar":"أستخدم كلمات بسيطة، وبعضها مكرر أو غير صحيح."},{"score":1,"descriptor":"I use very few words; the meaning is hard to understand.","descriptor_ar":"أستخدم كلمات قليلة جدًا ويصعب فهم المعنى."}]},{"name":"Sentence fluency","name_ar":"سلاسة الجمل","bands":[{"score":4,"descriptor":"My sentences are complete, varied in length and easy to read aloud.","descriptor_ar":"جملي كاملة ومتنوعة الطول وسهلة القراءة بصوت عالٍ."},{"score":3,"descriptor":"Most sentences are complete, with some variety.","descriptor_ar":"معظم جملي كاملة مع بعض التنويع."},{"score":2,"descriptor":"Many sentences are short or start the same way.","descriptor_ar":"كثير من جملي قصيرة أو تبدأ بالطريقة نفسها."},{"score":1,"descriptor":"Sentences are incomplete or run together.","descriptor_ar":"جملي ناقصة أو متداخلة."}]},{"name":"Conventions","name_ar":"قواعد الكتابة","bands":[{"score":4,"descriptor":"Capitals, punctuation, spelling and grammar are almost always correct.","descriptor_ar":"الحروف الكبيرة وعلامات الترقيم والإملاء والقواعد صحيحة دائمًا تقريبًا."},{"score":3,"descriptor":"A few mistakes that do not affect meaning.","descriptor_ar":"أخطاء قليلة لا تؤثر في المعنى."},{"score":2,"descriptor":"Several mistakes; the meaning is sometimes unclear.","descriptor_ar":"عدة أخطاء، والمعنى أحيانًا غير واضح."},{"score":1,"descriptor":"Many mistakes make it hard to read.","descriptor_ar":"أخطاء كثيرة تجعل القراءة صعبة."}]}]}],"lessons":[{"id":"RW-L01-U4-LS1","title":"Word Power: Animals Around Us","lesson_type":"vocabulary","objectives":["read and say 14 animal and movement words and 2 Tier 2 words (move, different)","use mime and pictures to learn movement words (run, fly, swim, jump)","say and write sentences about how animals move with *can*"],"objectives_ar":["قراءة ونطق 14 كلمة عن الحيوانات والحركة وكلمتين أكاديميتين (move, different).","استخدام التمثيل والصور لتعلم كلمات الحركة.","قول جمل وكتابتها عن كيفية تحرك الحيوانات باستخدام can."],"success_criteria":["I can read and say the animal words.","I can show and say how an animal moves.","I can say: A bird can fly."],"success_criteria_ar":["أستطيع قراءة أسماء الحيوانات ونطقها.","أستطيع تمثيل حركة الحيوان وقولها.","أستطيع قول: A bird can fly."],"map_area":"Vocabulary: Acquisition and Use","vocabulary":[{"word":"cat","pos":"noun","ipa":"/kæt/","definition":"a small animal with soft fur that says meow","arabic":"قطة","example":"The cat sleeps on the chair.","image_id":"IMG-RW-L01-U4-LS1-V01","audio_id":"AUD-RW-L01-U4-LS1-V01","tier":"core"},{"word":"dog","pos":"noun","ipa":"/dɔɡ/","definition":"an animal that barks; it can guard a farm","arabic":"كلب","example":"The farm dog runs fast.","image_id":"IMG-RW-L01-U4-LS1-V02","audio_id":"AUD-RW-L01-U4-LS1-V02","tier":"core"},{"word":"bird","pos":"noun","ipa":"/bɝd/","definition":"an animal with feathers and wings","arabic":"طائر","example":"A bird sits in the palm tree.","image_id":"IMG-RW-L01-U4-LS1-V03","audio_id":"AUD-RW-L01-U4-LS1-V03","tier":"core"},{"word":"fish","pos":"noun","ipa":"/fɪʃ/","definition":"an animal that lives and swims in water","arabic":"سمكة","example":"The fish is orange.","image_id":"IMG-RW-L01-U4-LS1-V04","audio_id":"AUD-RW-L01-U4-LS1-V04","tier":"core"},{"word":"camel","pos":"noun","ipa":"/ˈkæməl/","definition":"a big desert animal with a hump","arabic":"جمل","example":"The camel walks on the sand.","image_id":"IMG-RW-L01-U4-LS1-V05","audio_id":"AUD-RW-L01-U4-LS1-V05","tier":"core"},{"word":"horse","pos":"noun","ipa":"/hɔrs/","definition":"a big animal people can ride","arabic":"حصان","example":"The Arabian horse is beautiful.","image_id":"IMG-RW-L01-U4-LS1-V06","audio_id":"AUD-RW-L01-U4-LS1-V06","tier":"core"},{"word":"goat","pos":"noun","ipa":"/ɡoʊt/","definition":"a farm animal with horns that gives milk","arabic":"ماعز","example":"The goat eats grass.","image_id":"IMG-RW-L01-U4-LS1-V07","audio_id":"AUD-RW-L01-U4-LS1-V07","tier":"core"},{"word":"rabbit","pos":"noun","ipa":"/ˈræbɪt/","definition":"a small animal with long ears","arabic":"أرنب","example":"The rabbit has long ears.","image_id":"IMG-RW-L01-U4-LS1-V08","audio_id":"AUD-RW-L01-U4-LS1-V08","tier":"core"},{"word":"duck","pos":"noun","ipa":"/dʌk/","definition":"a bird that swims and says quack","arabic":"بطة","example":"The duck swims in the pond.","image_id":"IMG-RW-L01-U4-LS1-V09","audio_id":"AUD-RW-L01-U4-LS1-V09","tier":"core"},{"word":"run","pos":"verb","ipa":"/rʌn/","definition":"to move very fast on your legs","arabic":"يجري","example":"I run in the playground.","image_id":"IMG-RW-L01-U4-LS1-V10","audio_id":"AUD-RW-L01-U4-LS1-V10","tier":"core"},{"word":"fly","pos":"verb","ipa":"/flaɪ/","definition":"to move in the air with wings","arabic":"يطير","example":"Birds fly in the sky.","image_id":"IMG-RW-L01-U4-LS1-V11","audio_id":"AUD-RW-L01-U4-LS1-V11","tier":"core"},{"word":"swim","pos":"verb","ipa":"/swɪm/","definition":"to move in water","arabic":"يسبح","example":"Fish swim in the sea.","image_id":"IMG-RW-L01-U4-LS1-V12","audio_id":"AUD-RW-L01-U4-LS1-V12","tier":"core"},{"word":"jump","pos":"verb","ipa":"/dʒʌmp/","definition":"to push up off the ground with your legs","arabic":"يقفز","example":"The goat can jump on rocks.","image_id":"IMG-RW-L01-U4-LS1-V13","audio_id":"AUD-RW-L01-U4-LS1-V13","tier":"core"},{"word":"eat","pos":"verb","ipa":"/it/","definition":"to put food in your mouth","arabic":"يأكل","example":"The horse eats hay.","image_id":"IMG-RW-L01-U4-LS1-V14","audio_id":"AUD-RW-L01-U4-LS1-V14","tier":"core"},{"word":"move","pos":"verb","ipa":"/muv/","definition":"to go from one place to another","arabic":"يتحرك","example":"Animals move in many ways.","image_id":"IMG-RW-L01-U4-LS1-V15","audio_id":"AUD-RW-L01-U4-LS1-V15","tier":"tier2"},{"word":"different","pos":"adjective","ipa":"/ˈdɪfərənt/","definition":"not the same","arabic":"مختلف","example":"A fish and a bird are different.","image_id":"IMG-RW-L01-U4-LS1-V16","audio_id":"AUD-RW-L01-U4-LS1-V16","tier":"tier2"}],"explanation":{"text":"Animals **move** in **different** ways. We use **movement words**: *run, fly, swim, jump, walk*.\n\nLearn a movement word in three steps: **look** at the picture, **show** the move with your body, **say** the word.\n\nUse **can** to say what an animal is able to do: *A fish can swim.* Use **cannot** for what it is not able to do: *A fish cannot fly.*","examples":["Picture: a horse with flying legs → **run** → A horse can run.","Picture: a bird with open wings → **fly** → A bird can fly.","Picture: a fish in water → **swim** → A fish can swim.","Picture: a rabbit in the air → **jump** → A rabbit can jump.","Picture: a camel on sand → **walk** → A camel can walk on sand.","Picture: a duck on a pond → **swim** and **fly** → A duck can swim and fly.","Picture: a goat on rocks → **jump** → A goat can jump on rocks.","Picture: a cat with a fish bowl → **eat** → A cat can eat fish.","Not able: **A fish cannot walk. A camel cannot fly.**"],"common_errors":["✗ A bird can flies. → ✓ A bird can fly. (After **can**, use the plain action word.)","✗ A fish can to swim. → ✓ A fish can swim. (No **to** after can.)","✗ A camel no can fly. → ✓ A camel cannot fly. (Say **cannot**.)","✗ The fishes swim. → ✓ The fish swim. (**Fish** is the same for one and many.)","✗ I like the cats. → ✓ I like cats. (No *the* when you mean all cats.)","✗ The rabit jumps. → ✓ The rabbit jumps. (Spelling: ra**bb**it.)","✗ A horse can running. → ✓ A horse can run. (Use the plain word after can.)"],"arabic":"تتحرك الحيوانات بطرق مختلفة، ونستخدم كلمات الحركة مثل: run, fly, swim, jump, walk.\n\nتعلّم كلمة الحركة بثلاث خطوات: انظر إلى الصورة، ومثّل الحركة بجسمك، وقل الكلمة.\n\nنستخدم can لنقول ما يستطيع الحيوان فعله: A fish can swim، وcannot لما لا يستطيعه: A fish cannot fly.\n\nانتبه: بعد can نكتب الفعل كما هو دون s ودون to."},"video":{"script":[{"time":"00:00–00:15","narration":"Stand up! Today we move like animals!","on_screen":"Animals Around Us","visual":"Saqr flaps his wings; animals peek in from the sides of the screen."},{"time":"00:15–00:45","narration":"A horse can run. Run on the spot! A rabbit can jump. Jump!","on_screen":"run · jump","visual":"A horse gallops and a rabbit hops; a child silhouette copies the moves."},{"time":"00:45–01:15","narration":"A fish can swim. Move your arms! A bird can fly. Open your wings!","on_screen":"swim · fly","visual":"A fish swims through bubbles; a bird flies over palm trees."},{"time":"01:15–01:40","narration":"A duck can swim AND fly! A camel can walk on the sand.","on_screen":"swim + fly · walk","visual":"A duck lifts off a pond; a camel walks slowly over dunes."},{"time":"01:40–02:10","narration":"Can a fish walk? No! A fish cannot walk. Can a camel fly? No! A camel cannot fly!","on_screen":"can ✔ / cannot ✗","visual":"Funny 'no' moments: a fish with tiny legs (red X), a camel with paper wings (red X)."},{"time":"02:10–02:30","narration":"Animals move in different ways. How do YOU move?","on_screen":"How do you move?","visual":"Children run, jump and wave in a playground; Saqr cheers."}],"captions_ar":["قفوا! اليوم نتحرك مثل الحيوانات!","الحصان يجري. اجروا في أماكنكم! الأرنب يقفز. اقفزوا!","السمكة تسبح. حرّكوا أذرعكم! الطائر يطير. افتحوا أجنحتكم!","البطة تسبح وتطير! الجمل يمشي على الرمل.","هل تمشي السمكة؟ لا! هل يطير الجمل؟ لا!","الحيوانات تتحرك بطرق مختلفة. كيف تتحرك أنت؟"],"voice":"Narrator: American English, cheerful female teacher, speed 0.8. Saqr: playful. Animal sounds at low volume. Pauses for children to move."},"texts":[],"activities":[{"id":"RW-L01-U4-LS1-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Read and choose.","instructions_ar":"اقرأ واختر.","items":[{"q":"Which animal has a hump and walks on sand?","answer":"camel","explanation":"A camel has a hump.","explanation_ar":"للجمل سنام.","options":["camel","duck","rabbit","fish"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"Which animal has long ears and jumps?","answer":"rabbit","explanation":"Rabbits have long ears.","explanation_ar":"الأرنب له أذنان طويلتان.","options":["fish","rabbit","camel","bird"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"Which animal lives in water and cannot walk?","answer":"fish","explanation":"Fish live in water.","explanation_ar":"السمكة تعيش في الماء.","options":["fish","goat","horse","cat"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"A bird moves in the sky. It can ___.","answer":"fly","explanation":"Birds fly.","explanation_ar":"الطائر يطير.","options":["swim","jump","fly","eat"],"dok":1,"skill":"movement words","stage":"controlled"},{"q":"People can ride this big, fast animal.","answer":"horse","explanation":"We ride horses.","explanation_ar":"نركب الحصان.","options":["duck","rabbit","fish","horse"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"This farm animal has horns and gives milk.","answer":"goat","explanation":"Goats have horns and give milk.","explanation_ar":"للماعز قرون.","options":["cat","goat","bird","fish"],"dok":1,"skill":"vocabulary","stage":"controlled"}]},{"id":"RW-L01-U4-LS1-A2","type":"gap_fill","stage":"guided","instructions":"Guided practice: Complete with a word from the bank.","instructions_ar":"أكمل بكلمة من البنك.","items":[{"q":"A duck can ________ in the pond.","answer":"swim","explanation":"Ducks swim.","explanation_ar":"البط يسبح.","stage":"guided"},{"q":"The horse can ________ very fast.","answer":"run","explanation":"Horses run fast.","explanation_ar":"الحصان يجري بسرعة.","stage":"guided"},{"q":"The goat can ________ on the rocks.","answer":"jump","explanation":"Goats jump on rocks.","explanation_ar":"الماعز يقفز على الصخور.","stage":"guided"},{"q":"The cat likes to ________ fish.","answer":"eat","explanation":"Cats eat fish.","explanation_ar":"القطة تأكل السمك.","stage":"guided"},{"q":"Animals ________ in different ways.","answer":"move","explanation":"Move = go from place to place.","explanation_ar":"الحيوانات تتحرك.","stage":"guided"},{"q":"A fish and a camel are very ________.","answer":"different","explanation":"They are not the same.","explanation_ar":"مختلفان.","stage":"guided"}]},{"id":"RW-L01-U4-LS1-A3","type":"open","stage":"freer","instructions":"Freer practice: Can or cannot? Write a sentence.","instructions_ar":"يستطيع أم لا يستطيع؟ اكتب جملة.","items":[{"q":"fish / walk","answer":"A fish cannot walk.","explanation":"Fish cannot walk.","explanation_ar":"السمكة لا تمشي.","dok":1,"skill":"can/cannot","stage":"freer"},{"q":"bird / fly","answer":"A bird can fly.","explanation":"Birds can fly.","explanation_ar":"الطائر يطير.","dok":1,"skill":"can/cannot","stage":"freer"},{"q":"camel / fly","answer":"A camel cannot fly.","explanation":"Camels cannot fly.","explanation_ar":"الجمل لا يطير.","dok":1,"skill":"can/cannot","stage":"freer"},{"q":"duck / swim","answer":"A duck can swim.","explanation":"Ducks can swim.","explanation_ar":"البطة تسبح.","dok":1,"skill":"can/cannot","stage":"freer"}]},{"id":"RW-L01-U4-LS1-A4","type":"open","stage":"production","instructions":"Writing: Write about animals you know.","instructions_ar":"اكتب عن حيوانات تعرفها.","items":[{"q":"What is your favorite animal? How does it move?","answer":"My favorite animal is the horse. It can run.","explanation":"Animal + can + move.","explanation_ar":"حيوان + can + حركة.","dok":2,"skill":"personal writing","stage":"production"},{"q":"Write an animal that can jump.","answer":"A rabbit can jump.","explanation":"A ___ can jump.","explanation_ar":"جملة بـ can jump.","dok":1,"skill":"can","stage":"production"},{"q":"Write something YOU can do. Use a movement word.","answer":"I can swim.","explanation":"I can + move.","explanation_ar":"I can + حركة.","dok":1,"skill":"can","stage":"production"},{"q":"Draw an animal. Write a label for its legs, ears or wings.","answer":"wings","explanation":"A correct label.","explanation_ar":"بطاقة صحيحة.","dok":1,"skill":"labelling","stage":"production"}]}],"game":{"name":"Animal Move Freeze","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Match-the-move: an animal appears; the child taps one of four movement icons (run, fly, swim, jump). Correct = the animal moves across the screen with its sound. 14 animals; some have two right answers (duck: swim/fly).","Music plays; students walk around.","The music stops and the teacher shows an animal card.","Students freeze in that animal's move (bird = arms out).","The teacher points to a student, who says: \"A bird can fly!\"","Correct sentence = the student chooses the next animal card."],"data":[]},"exit_quiz":[{"q":"Which animal can fly?","answer":"bird","explanation":"Birds have wings and fly.","explanation_ar":"الطائر يطير.","options":["fish","bird","camel","goat"],"dok":1,"skill":"movement"},{"q":"Which animal can swim?","answer":"fish","explanation":"Fish swim in water.","explanation_ar":"السمكة تسبح.","options":["rabbit","horse","camel","fish"],"dok":1,"skill":"movement"},{"q":"Which word is a movement word?","answer":"jump","explanation":"Jump is a move.","explanation_ar":"jump حركة.","options":["goat","rabbit","different","jump"],"dok":1,"skill":"movement words"},{"q":"A ___ is a big desert animal.","answer":"camel","explanation":"Camels live in the desert.","explanation_ar":"الجمل حيوان صحراوي.","options":["camel","duck","cat","fish"],"dok":1,"skill":"vocabulary"},{"q":"Which sentence about the duck is correct?","answer":"A duck can swim.","explanation":"After can, use the plain word.","explanation_ar":"بعد can الفعل كما هو.","options":["A duck can swims.","A duck can to swim.","A duck can swim.","A duck swim can."],"dok":2,"skill":"can"},{"q":"Which sentence is TRUE?","answer":"A fish cannot walk.","explanation":"Fish do not have legs.","explanation_ar":"السمكة لا تمشي.","options":["A fish cannot walk.","A camel can fly.","A goat can swim in the sky.","A rabbit cannot jump."],"dok":2,"skill":"can/cannot"},{"q":"*Different* means ___.","answer":"not the same","explanation":"Different = not the same.","explanation_ar":"مختلف = ليس متشابهًا.","options":["very big","very fast","not the same","the same"],"dok":1,"skill":"vocabulary"},{"q":"Which animal can swim AND fly?","answer":"duck","explanation":"Ducks swim and fly.","explanation_ar":"البطة تسبح وتطير.","options":["cat","horse","duck","goat"],"dok":2,"skill":"movement"},{"q":"Picture: an animal with four long legs and a flying mane. How does it move?","answer":"It runs fast.","explanation":"A horse with a flying mane is running.","explanation_ar":"الحصان يجري.","options":["It swims.","It flies.","It hops in water.","It runs fast."],"dok":2,"skill":"picture clue"},{"q":"Why can a bird fly but a cat cannot?","answer":"A bird has wings.","explanation":"Wings help birds fly.","explanation_ar":"الأجنحة تساعد الطائر على الطيران.","options":["A cat is happy.","A bird has wings.","A bird is big.","A cat lives in water."],"dok":3,"skill":"reasoning"}],"images":[{"id":"IMG-RW-L01-U4-LS1-V01","prompt":"Picture for the word 'cat': a grey cat curled on a chair"},{"id":"IMG-RW-L01-U4-LS1-V02","prompt":"Picture for the word 'dog': a slim saluki dog running on a farm"},{"id":"IMG-RW-L01-U4-LS1-V03","prompt":"Picture for the word 'bird': a small colorful bird on a palm branch"},{"id":"IMG-RW-L01-U4-LS1-V04","prompt":"Picture for the word 'fish': an orange fish swimming"},{"id":"IMG-RW-L01-U4-LS1-V05","prompt":"Picture for the word 'camel': a camel walking on sand dunes"},{"id":"IMG-RW-L01-U4-LS1-V06","prompt":"Picture for the word 'horse': a white Arabian horse galloping"},{"id":"IMG-RW-L01-U4-LS1-V07","prompt":"Picture for the word 'goat': a brown goat eating grass"},{"id":"IMG-RW-L01-U4-LS1-V08","prompt":"Picture for the word 'rabbit': a white rabbit with long ears"},{"id":"IMG-RW-L01-U4-LS1-V09","prompt":"Picture for the word 'duck': a duck on a pond"},{"id":"IMG-RW-L01-U4-LS1-V10","prompt":"Picture for the word 'run': a boy running with motion lines"},{"id":"IMG-RW-L01-U4-LS1-V11","prompt":"Picture for the word 'fly': birds flying over a city"},{"id":"IMG-RW-L01-U4-LS1-V12","prompt":"Picture for the word 'swim': a fish swimming among bubbles"},{"id":"IMG-RW-L01-U4-LS1-V13","prompt":"Picture for the word 'jump': a goat jumping between rocks"},{"id":"IMG-RW-L01-U4-LS1-V14","prompt":"Picture for the word 'eat': a horse eating hay"},{"id":"IMG-RW-L01-U4-LS1-V15","prompt":"Picture for the word 'move': arrows showing a bird flying, a fish swimming and a rabbit jumping"},{"id":"IMG-RW-L01-U4-LS1-V16","prompt":"Picture for the word 'different': a fish and a bird side by side"},{"id":"IMG-RW-L01-U4-LS1-01","prompt":"Sami and Omar see many animals on a farm."},{"id":"IMG-RW-L01-U4-LS1-02","prompt":"Four animals running, flying, swimming and jumping."},{"id":"IMG-RW-L01-U4-LS1-03","prompt":"A fish with legs and a camel with paper wings, both marked with an X."}],"audio":[{"id":"AUD-RW-L01-U4-LS1-V01","script":"cat. The cat sleeps on the chair."},{"id":"AUD-RW-L01-U4-LS1-V02","script":"dog. The farm dog runs fast."},{"id":"AUD-RW-L01-U4-LS1-V03","script":"bird. A bird sits in the palm tree."},{"id":"AUD-RW-L01-U4-LS1-V04","script":"fish. The fish is orange."},{"id":"AUD-RW-L01-U4-LS1-V05","script":"camel. The camel walks on the sand."},{"id":"AUD-RW-L01-U4-LS1-V06","script":"horse. The Arabian horse is beautiful."},{"id":"AUD-RW-L01-U4-LS1-V07","script":"goat. The goat eats grass."},{"id":"AUD-RW-L01-U4-LS1-V08","script":"rabbit. The rabbit has long ears."},{"id":"AUD-RW-L01-U4-LS1-V09","script":"duck. The duck swims in the pond."},{"id":"AUD-RW-L01-U4-LS1-V10","script":"run. I run in the playground."},{"id":"AUD-RW-L01-U4-LS1-V11","script":"fly. Birds fly in the sky."},{"id":"AUD-RW-L01-U4-LS1-V12","script":"swim. Fish swim in the sea."},{"id":"AUD-RW-L01-U4-LS1-V13","script":"jump. The goat can jump on rocks."},{"id":"AUD-RW-L01-U4-LS1-V14","script":"eat. The horse eats hay."},{"id":"AUD-RW-L01-U4-LS1-V15","script":"move. Animals move in many ways."},{"id":"AUD-RW-L01-U4-LS1-V16","script":"different. A fish and a bird are different."},{"id":"AUD-RW-L01-U4-LS1-VID","script":"Stand up! Today we move like animals! A horse can run. Run on the spot! A rabbit can jump. Jump! A fish can swim. Move your arms! A bird can fly. Open your wings! A duck can swim AND fly! A camel can walk on the sand. Can a fish walk? No! A fish cannot walk. Can a camel fly? No! A camel cannot fly! Animals move in different ways. How do YOU move?"}]},{"id":"RW-L01-U4-LS2","title":"Animals on the Move","lesson_type":"close_reading","objectives":["read a short information text (about 85 words) and say what it is about","find facts about animals and how they move, with evidence","tell a fact from a story sentence (true about the real world vs. made up)"],"objectives_ar":["قراءة نص معلوماتي قصير (نحو 85 كلمة) وقول موضوعه.","إيجاد حقائق عن الحيوانات وكيف تتحرك مع الدليل.","التمييز بين الحقيقة وجملة القصة الخيالية."],"success_criteria":["I can read the information text.","I can find facts in the text.","I can say if a sentence is a fact."],"success_criteria_ar":["أستطيع قراءة النص المعلوماتي.","أستطيع إيجاد الحقائق في النص.","أستطيع قول ما إذا كانت الجملة حقيقة."],"map_area":"Informational Text: Key Ideas and Details","vocabulary":[{"word":"way","pos":"noun","ipa":"/weɪ/","definition":"how you do something","arabic":"طريقة","example":"There are many ways to say hello.","image_id":"IMG-RW-L01-U4-LS2-V01","audio_id":"AUD-RW-L01-U4-LS2-V01","tier":"core"},{"word":"wings","pos":"noun","ipa":"/wɪŋz/","definition":"the parts a bird uses to fly","arabic":"أجنحة","example":"The bird opens its wings.","image_id":"IMG-RW-L01-U4-LS2-V02","audio_id":"AUD-RW-L01-U4-LS2-V02","tier":"core"},{"word":"legs","pos":"noun","ipa":"/lɛɡz/","definition":"the long parts of a body for walking","arabic":"أرجل","example":"A horse has four legs.","image_id":"IMG-RW-L01-U4-LS2-V03","audio_id":"AUD-RW-L01-U4-LS2-V03","tier":"core"},{"word":"sky","pos":"noun","ipa":"/skaɪ/","definition":"the space above us where we see the sun and clouds","arabic":"سماء","example":"The sky is blue.","image_id":"IMG-RW-L01-U4-LS2-V04","audio_id":"AUD-RW-L01-U4-LS2-V04","tier":"core"},{"word":"desert","pos":"noun","ipa":"/ˈdɛzərt/","definition":"a hot, dry place with sand","arabic":"صحراء","example":"Camels live in the desert.","image_id":"IMG-RW-L01-U4-LS2-V05","audio_id":"AUD-RW-L01-U4-LS2-V05","tier":"core"},{"word":"high","pos":"adverb","ipa":"/haɪ/","definition":"far up from the ground","arabic":"عاليًا","example":"The ball goes high.","image_id":"IMG-RW-L01-U4-LS2-V06","audio_id":"AUD-RW-L01-U4-LS2-V06","tier":"core"},{"word":"fact","pos":"noun","ipa":"/fækt/","definition":"something that is true","arabic":"حقيقة","example":"It is a fact that fish swim.","image_id":"IMG-RW-L01-U4-LS2-V07","audio_id":"AUD-RW-L01-U4-LS2-V07","tier":"core"}],"explanation":{"text":"An **information text** tells us **facts**. A fact is something **true** about the real world.\n\nA story can have made-up things (a talking camel!). An information text has **real** things.\n\nTo find a fact, ask: **Who or what** is it about? **What can it do?** Point to the sentence.","examples":["Fact: **A horse can run fast.**","Fact: **A bird has wings.**","Fact: **A fish lives in water.**","Fact: **A fish cannot walk.**","Fact: **A rabbit has long legs.**","Fact: **A goat can jump on rocks.**","Fact: **A duck can fly and swim.**","Not a fact (made up): *The camel said, \"Hello!\"* – camels cannot talk.","Not a fact (made up): *The fish flew to the moon.*"],"common_errors":["✗ A fish live in water. → ✓ A fish lives in water. (One fish → **lives**.)","✗ A bird have wings. → ✓ A bird has wings. (One bird → **has**.)","✗ The rabbit legs is long. → ✓ The rabbit's legs are long. (Use **'s** and **are** for legs.)","✗ It can jump very higher. → ✓ It can jump very high. (Say **very high**.)","✗ Camel can run. → ✓ A camel can run. (Use **a** before one animal.)","✗ in the sky up → ✓ up in the sky (Word order: **up in the sky**.)"],"arabic":"النص المعلوماتي يخبرنا بحقائق، والحقيقة شيء صحيح في العالم الحقيقي.\n\nالقصة قد تحتوي على أشياء خيالية مثل جمل يتكلم، أما النص المعلوماتي ففيه أشياء حقيقية.\n\nلتجد الحقيقة اسأل: عن ماذا يتحدث؟ ماذا يستطيع أن يفعل؟ ثم أشِر إلى الجملة.\n\nانتبه: نقول A fish lives وA bird has مع المفرد."},"video":{"script":[{"time":"00:00–00:20","narration":"Is it true? Today we look for facts!","on_screen":"Fact Finders 🔍","visual":"Saqr in a safari hat holds binoculars."},{"time":"00:20–01:15","narration":"Animals move in many ways. Run – A horse can run fast…","on_screen":"(text, section by section)","visual":"Each section heading appears in coral; real-looking animal illustrations move as the facts are read."},{"time":"01:15–01:40","narration":"A fact is true in the real world. A horse can run fast – true! That is a fact.","on_screen":"Fact = true ✔","visual":"A big green tick stamps the horse sentence."},{"time":"01:40–02:05","narration":"The camel says, 'Hello!' Is that a fact? No! Camels cannot talk. That is made up.","on_screen":"Made up ✗","visual":"A cartoon camel with a speech bubble gets a playful red X."},{"time":"02:05–02:30","narration":"Find the animal, find what it can do, point to the sentence. You are a fact finder!","on_screen":"Animal → can do → point","visual":"Three icons appear; Saqr salutes."}],"captions_ar":["هل هذا صحيح؟ اليوم نبحث عن الحقائق!","تتحرك الحيوانات بطرق كثيرة. الجري: الحصان يجري بسرعة…","الحقيقة شيء صحيح في العالم الحقيقي: الحصان يجري بسرعة، هذه حقيقة.","الجمل يقول: مرحبًا! هل هذه حقيقة؟ لا! الجمال لا تتكلم، هذا خيال.","ابحث عن الحيوان، وعما يستطيع فعله، وأشر إلى الجملة. أنت باحث عن الحقائق!"],"voice":"Narrator: American English, clear female 'documentary' voice for children, speed 0.8, curious tone."},"texts":[{"type":"reading","title":"Animals on the Move","body":"Animals move in many ways.\n\n**Run** – A horse can run fast. A camel can run in the desert. A dog can run and jump too!\n\n**Fly** – A bird has wings. It can fly up in the sky. A duck can fly and swim.\n\n**Swim** – A fish lives in water. It can swim, but it cannot walk.\n\n**Jump** – A rabbit has long legs. It can jump very high. A goat can jump on rocks. A cat can jump on a wall.\n\nHow do YOU move?","word_count":84,"audio_id":"AUD-RW-L01-U4-LS2-T1","id":"TXT-RW-L01-U4-LS2-1","genre":"informational","role":"main","difficulty":"BR–200L","glossary":[{"word":"wings","definition":"the parts a bird uses to fly","arabic":"أجنحة"},{"word":"rocks","definition":"big hard stones","arabic":"صخور"}]}],"activities":[{"id":"RW-L01-U4-LS2-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Read the text. Choose the fact.","instructions_ar":"اقرأ النص واختر الحقيقة.","items":[{"q":"What is *Animals on the Move* mostly about?","answer":"how animals move","explanation":"Every part tells how animals move.","explanation_ar":"النص عن حركة الحيوانات.","options":["what animals eat","where children play","how animals move","how to pack a bag"],"dok":1,"skill":"main topic","stage":"controlled"},{"q":"Which animal can run in the desert?","answer":"a camel","explanation":"Text: A camel can run in the desert.","explanation_ar":"الجمل.","options":["a fish","a duck","a rabbit","a camel"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"What does a bird have?","answer":"wings","explanation":"Text: A bird has wings.","explanation_ar":"للطائر أجنحة.","options":["long ears","wings","a hump","horns"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"Where does a fish live?","answer":"in water","explanation":"Text: A fish lives in water.","explanation_ar":"تعيش في الماء.","options":["in water","in the desert","in the sky","on rocks"],"dok":1,"skill":"key details: where","stage":"controlled"},{"q":"What can a goat jump on?","answer":"rocks","explanation":"Text: A goat can jump on rocks.","explanation_ar":"على الصخور.","options":["rocks","water","the sky","a duck"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"What does a rabbit have that helps it jump?","answer":"long legs","explanation":"Text: A rabbit has long legs.","explanation_ar":"أرجل طويلة.","options":["wings","a hump","long legs","fins"],"dok":1,"skill":"key details","stage":"controlled"}]},{"id":"RW-L01-U4-LS2-A2","type":"true_false","stage":"guided","instructions":"Guided practice: Fact check: true or false?","instructions_ar":"تحقق من الحقيقة: صح أم خطأ؟","items":[{"q":"A horse can run fast.","answer":"true","explanation":"Text: A horse can run fast.","explanation_ar":"صحيح.","options":["true","false"],"stage":"guided"},{"q":"A fish can walk.","answer":"false","explanation":"Text: it cannot walk.","explanation_ar":"السمكة لا تمشي.","options":["true","false"],"stage":"guided"},{"q":"A duck can fly and swim.","answer":"true","explanation":"Text: A duck can fly and swim.","explanation_ar":"صحيح.","options":["true","false"],"stage":"guided"},{"q":"A dog can run and jump.","answer":"true","explanation":"Text: A dog can run and jump too!","explanation_ar":"صحيح.","options":["true","false"],"stage":"guided"},{"q":"A cat can jump on a wall.","answer":"true","explanation":"Text: A cat can jump on a wall.","explanation_ar":"صحيح.","options":["true","false"],"stage":"guided"},{"q":"A rabbit has short legs.","answer":"false","explanation":"Text: long legs.","explanation_ar":"أرجله طويلة.","options":["true","false"],"stage":"guided"}]},{"id":"RW-L01-U4-LS2-A3","type":"highlight","stage":"freer","instructions":"Find the evidence: Find the facts. Underline or choose.","instructions_ar":"ابحث عن الحقائق: ضع خطًا أو اختر.","items":[{"q":"Underline the fact that tells where a bird can fly.","answer":"It can fly up in the sky.","explanation":"This sentence tells where.","explanation_ar":"هذه الجملة تذكر المكان.","evidence":"It can fly up in the sky.","text_id":"TXT-RW-L01-U4-LS2-1","dok":1,"skill":"evidence","stage":"freer","sentences":["Animals move in many ways.","**Run** – A horse can run fast.","A camel can run in the desert.","A dog can run and jump too!","**Fly** – A bird has wings.","It can fly up in the sky.","A duck can fly and swim.","**Swim** – A fish lives in water.","It can swim, but it cannot walk.","**Jump** – A rabbit has long legs.","It can jump very high.","A goat can jump on rocks.","A cat can jump on a wall.","How do YOU move?"]},{"q":"Underline the fact that tells what a fish cannot do.","answer":"It can swim, but it cannot walk.","explanation":"Cannot walk.","explanation_ar":"لا تمشي.","evidence":"It can swim, but it cannot walk.","text_id":"TXT-RW-L01-U4-LS2-1","dok":1,"skill":"evidence","stage":"freer","sentences":["Animals move in many ways.","**Run** – A horse can run fast.","A camel can run in the desert.","A dog can run and jump too!","**Fly** – A bird has wings.","It can fly up in the sky.","A duck can fly and swim.","**Swim** – A fish lives in water.","It can swim, but it cannot walk.","**Jump** – A rabbit has long legs.","It can jump very high.","A goat can jump on rocks.","A cat can jump on a wall.","How do YOU move?"]},{"q":"Which sentence is made up, NOT a fact?","answer":"The goat sang a song.","explanation":"Goats cannot sing.","explanation_ar":"الماعز لا يغني.","options":["A goat can jump on rocks.","A horse can run fast.","A bird has wings.","The goat sang a song."],"dok":2,"skill":"fact vs. made up","stage":"freer"},{"q":"Why do you think a camel can run in the desert?","answer":"It lives there and can walk on sand.","explanation":"Camels live in deserts.","explanation_ar":"الجمل يعيش في الصحراء.","options":["It has wings.","It lives there and can walk on sand.","It lives in water.","It is very small."],"dok":2,"skill":"inference","stage":"freer"}]},{"id":"RW-L01-U4-LS2-A4","type":"open","stage":"production","instructions":"Writing: Write facts.","instructions_ar":"اكتب حقائق.","items":[{"q":"Write one fact from the text about a horse.","answer":"A horse can run fast.","explanation":"A true sentence from the text.","explanation_ar":"جملة صحيحة من النص.","dok":1,"skill":"facts","stage":"production"},{"q":"Write one fact about an animal NOT in the text.","answer":"A cow gives milk.","explanation":"A true sentence.","explanation_ar":"جملة صحيحة.","dok":2,"skill":"facts","stage":"production"},{"q":"How do YOU move? Write two ways.","answer":"I can run and jump.","explanation":"I can + two moves.","explanation_ar":"I can + حركتان.","dok":1,"skill":"connect","stage":"production"},{"q":"Write one made-up sentence about an animal for a friend to find.","answer":"The rabbit drives a bus.","explanation":"A funny, not-true sentence.","explanation_ar":"جملة خيالية مضحكة.","dok":2,"skill":"fact vs. made up","stage":"production"}]},{"id":"RW-L01-U4-LS2-TR-1","type":"timed_reading","instructions":"Timed reading: Read \"Animals on the Move\" aloud or silently. Try to finish in the time.","instructions_ar":"اقرأ النص وحاول أن تنهيه في الوقت المحدد.","items":[{"q":"Read “Animals on the Move”.","answer":"84 words","title":"Animals on the Move","body":"Animals move in many ways.\n\n**Run** – A horse can run fast. A camel can run in the desert. A dog can run and jump too!\n\n**Fly** – A bird has wings. It can fly up in the sky. A duck can fly and swim.\n\n**Swim** – A fish lives in water. It can swim, but it cannot walk.\n\n**Jump** – A rabbit has long legs. It can jump very high. A goat can jump on rocks. A cat can jump on a wall.\n\nHow do YOU move?","words":84,"limit":141}],"time_limit_sec":141}],"game":{"name":"Fact or Fib?","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Swipe: a sentence with an animal picture appears; swipe up for FACT, down for FIB. Correct facts add an animal to a zoo map. 12 cards, 8 seconds each.","Every student has a FACT card and a FIB card.","The teacher reads a sentence card.","Students show one card on \"3!\"","The teacher shows the answer; for facts, students find the sentence in the text if it is there.","Students keep a tally; 10/12 or more = Fact Finder badge."],"data":[]},"exit_quiz":[{"q":"What kind of text is *Animals on the Move*?","answer":"an information text","explanation":"It gives facts.","explanation_ar":"نص معلوماتي.","options":["a story","a note","an information text","a poem"],"dok":1,"skill":"genre"},{"q":"A fact is something that is ___.","answer":"true","explanation":"Facts are true.","explanation_ar":"الحقيقة صحيحة.","options":["funny","made up","true","very long"],"dok":1,"skill":"strategy"},{"q":"Which animal can jump very high?","answer":"a rabbit","explanation":"Text: It can jump very high.","explanation_ar":"الأرنب.","options":["a fish","a camel","a duck","a rabbit"],"dok":1,"skill":"key details"},{"q":"What can a bird do with its wings?","answer":"fly","explanation":"Wings help birds fly.","explanation_ar":"يطير.","options":["swim","walk on rocks","jump on a wall","fly"],"dok":1,"skill":"key details"},{"q":"In the text, which animal can fly AND swim?","answer":"a duck","explanation":"Text: A duck can fly and swim.","explanation_ar":"البطة.","options":["a horse","a duck","a goat","a cat"],"dok":1,"skill":"key details"},{"q":"Which part tells about the fish?","answer":"the *Swim* part","explanation":"The fish is in the Swim part.","explanation_ar":"في جزء Swim.","options":["the *Swim* part","the *Run* part","the *Fly* part","the *Jump* part"],"dok":2,"skill":"text structure"},{"q":"Which sentence is a fact?","answer":"A goat can jump on rocks.","explanation":"This is true.","explanation_ar":"هذه حقيقة.","options":["A goat can jump on rocks.","A goat can read books.","A goat flies to school.","A goat is a fish."],"dok":1,"skill":"fact"},{"q":"*A fish lives in water.* What does *lives* mean here?","answer":"has its home","explanation":"Lives = has its home.","explanation_ar":"lives تعني يعيش/يسكن.","options":["is very happy","has its home","swims fast","eats"],"dok":2,"skill":"word in context"},{"q":"Why does the text end with *How do YOU move?*","answer":"to make the reader think about himself","explanation":"The question asks the reader.","explanation_ar":"ليجعل القارئ يفكر في نفسه.","options":["to make the reader think about himself","to tell a new fact","to say goodbye","to give a title"],"dok":3,"skill":"author's purpose"},{"q":"Which animal from the text could you see in a Saudi desert?","answer":"a camel","explanation":"Camels live in the desert.","explanation_ar":"الجمل في الصحراء.","options":["a fish","a duck on a pond","a rabbit on a wall","a camel"],"dok":2,"skill":"connect"}],"images":[{"id":"IMG-RW-L01-U4-LS2-V01","prompt":"Picture for the word 'way': three children greeting in different ways: wave, handshake, smile"},{"id":"IMG-RW-L01-U4-LS2-V02","prompt":"Picture for the word 'wings': a bird with wings spread wide"},{"id":"IMG-RW-L01-U4-LS2-V03","prompt":"Picture for the word 'legs': a horse with its four legs clearly shown"},{"id":"IMG-RW-L01-U4-LS2-V04","prompt":"Picture for the word 'sky': blue sky with white clouds"},{"id":"IMG-RW-L01-U4-LS2-V05","prompt":"Picture for the word 'desert': golden sand dunes"},{"id":"IMG-RW-L01-U4-LS2-V06","prompt":"Picture for the word 'high': a ball high in the air above children"},{"id":"IMG-RW-L01-U4-LS2-V07","prompt":"Picture for the word 'fact': a tick mark next to a picture of a fish swimming"},{"id":"IMG-RW-L01-U4-LS2-01","prompt":"A horse and a camel run while a bird and a duck fly."},{"id":"IMG-RW-L01-U4-LS2-02","prompt":"A fish swims while a rabbit, a goat and a cat jump."},{"id":"IMG-RW-L01-U4-LS2-03","prompt":"Saqr in a safari hat with binoculars."}],"audio":[{"id":"AUD-RW-L01-U4-LS2-V01","script":"way. There are many ways to say hello."},{"id":"AUD-RW-L01-U4-LS2-V02","script":"wings. The bird opens its wings."},{"id":"AUD-RW-L01-U4-LS2-V03","script":"legs. A horse has four legs."},{"id":"AUD-RW-L01-U4-LS2-V04","script":"sky. The sky is blue."},{"id":"AUD-RW-L01-U4-LS2-V05","script":"desert. Camels live in the desert."},{"id":"AUD-RW-L01-U4-LS2-V06","script":"high. The ball goes high."},{"id":"AUD-RW-L01-U4-LS2-V07","script":"fact. It is a fact that fish swim."},{"id":"AUD-RW-L01-U4-LS2-T1","script":"Animals move in many ways. **Run** – A horse can run fast. A camel can run in the desert. A dog can run and jump too! **Fly** – A bird has wings. It can fly up in the sky. A duck can fly and swim. **Swim** – A fish lives in water. It can swim, but it cannot walk. **Jump** – A rabbit has long legs. It can jump very high. A goat can jump on rocks. A cat can jump on a wall. How do YOU move?"},{"id":"AUD-RW-L01-U4-LS2-VID","script":"Is it true? Today we look for facts! Animals move in many ways. Run – A horse can run fast… A fact is true in the real world. A horse can run fast – true! That is a fact. The camel says, 'Hello!' Is that a fact? No! Camels cannot talk. That is made up. Find the animal, find what it can do, point to the sentence. You are a fact finder!"}]},{"id":"RW-L01-U4-LS3","title":"Text features: title, picture, label: \"Hop, Run, Fly!\"","lesson_type":"strategy_paired_text","objectives":["name text features: title, heading, picture, label and caption","use text features to find information quickly","compare the features of an information text and a poem"],"objectives_ar":["تسمية سمات النص: العنوان، والعنوان الفرعي، والصورة، والبطاقة، والتعليق.","استخدام سمات النص لإيجاد المعلومات بسرعة.","مقارنة سمات النص المعلوماتي والقصيدة."],"success_criteria":["I can find the title, headings, pictures and labels.","I can use a feature to find an answer fast.","I can say how a poem looks different."],"success_criteria_ar":["أستطيع إيجاد العنوان والعناوين الفرعية والصور والبطاقات.","أستطيع استخدام سمة النص لإيجاد الإجابة بسرعة.","أستطيع قول كيف تبدو القصيدة مختلفة."],"map_area":"Literary Text: Language, Craft, and Structure","vocabulary":[{"word":"heading","pos":"noun","ipa":"/ˈhɛdɪŋ/","definition":"the name of one part of a text","arabic":"عنوان فرعي","example":"The heading says *Swim*.","image_id":"IMG-RW-L01-U4-LS3-V01","audio_id":"AUD-RW-L01-U4-LS3-V01","tier":"core"},{"word":"caption","pos":"noun","ipa":"/ˈkæpʃən/","definition":"a sentence under a picture that tells about it","arabic":"تعليق على الصورة","example":"Read the caption under the photo.","image_id":"IMG-RW-L01-U4-LS3-V02","audio_id":"AUD-RW-L01-U4-LS3-V02","tier":"core"},{"word":"label","pos":"noun","ipa":"/ˈleɪbəl/","definition":"a word with a line to a part of a picture","arabic":"بطاقة / تسمية","example":"The label says *wing*.","image_id":"IMG-RW-L01-U4-LS3-V03","audio_id":"AUD-RW-L01-U4-LS3-V03","tier":"core"},{"word":"feature","pos":"noun","ipa":"/ˈfitʃər/","definition":"a special part that helps you","arabic":"سمة / ميزة","example":"A title is a text feature.","image_id":"IMG-RW-L01-U4-LS3-V04","audio_id":"AUD-RW-L01-U4-LS3-V04","tier":"core"},{"word":"hop","pos":"verb","ipa":"/hɑp/","definition":"to make small jumps","arabic":"يقفز قفزات صغيرة","example":"The bird hops on the grass.","image_id":"IMG-RW-L01-U4-LS3-V05","audio_id":"AUD-RW-L01-U4-LS3-V05","tier":"core"},{"word":"sea","pos":"noun","ipa":"/si/","definition":"a very big area of salt water","arabic":"بحر","example":"The Red Sea is beautiful.","image_id":"IMG-RW-L01-U4-LS3-V06","audio_id":"AUD-RW-L01-U4-LS3-V06","tier":"core"},{"word":"slow","pos":"adjective","ipa":"/sloʊ/","definition":"not fast","arabic":"بطيء","example":"The turtle is slow.","image_id":"IMG-RW-L01-U4-LS3-V07","audio_id":"AUD-RW-L01-U4-LS3-V07","tier":"core"}],"explanation":{"text":"**Text features** are special parts of a text. They help you find information fast.\n\n**Title** – the name of the whole text. **Heading** – the name of one part. **Picture** – shows what the words say.\n\n**Label** – a word with a line to a part of a picture. **Caption** – a sentence under a picture.\n\nA poem has a **title** and **lines**. Many poems have **rhyming** words at the end of lines.","examples":["Title: **Animals on the Move** → the text is about how animals move.","Heading: **Swim** → this part tells about animals that swim.","Heading: **Jump** → look here to learn about the rabbit and the goat.","Picture: a bird with open wings → it shows *A bird can fly*.","Label: **wing** → the line points to the bird's wing.","Label: **hump** → the line points to the camel's back.","Caption: **A camel walks on hot sand.** → it tells about the camel picture.","Poem title: **Hop, Run, Fly!** → the poem is about moving.","Poem lines: *sun / fun*, *sea / tree* → rhyming words."],"common_errors":["✗ The heading is the first sentence. → ✓ The heading is the name of a part, above it. (A heading is not a sentence.)","✗ The label is under the picture and long. → ✓ A caption is under the picture; a label is one word with a line. (Do not mix label and caption.)","✗ Hop, Run, Fly is a story. → ✓ *Hop, Run, Fly!* is a poem. (It has lines and rhymes.)","✗ I read the title in the end. → ✓ I read the title first. (The title is at the top.)","✗ The camel is slowly. → ✓ The camel is slow. (After **is**, use **slow**.)","✗ in sea → ✓ in the sea (Say **the sea**.)"],"arabic":"سمات النص أجزاء خاصة تساعدك على إيجاد المعلومات بسرعة.\n\nالعنوان (title) اسم النص كله، والعنوان الفرعي (heading) اسم جزء منه، والصورة توضّح الكلام.\n\nالبطاقة (label) كلمة يخرج منها خط إلى جزء من الصورة، والتعليق (caption) جملة تحت الصورة.\n\nالقصيدة لها عنوان وأسطر، وكثير من القصائد فيها كلمات متناغمة في نهايات الأسطر."},"video":{"script":[{"time":"00:00–00:15","narration":"Texts have helpers! They are called text features.","on_screen":"Text features 🧰","visual":"A toolbox opens; tools labelled with icons (title, heading, picture, label, caption) jump out."},{"time":"00:15–00:50","narration":"The title is the name of the text. Headings are names of parts: Run, Fly, Swim, Jump.","on_screen":"Title · Headings","visual":"The title glows at the top of 'Animals on the Move'; headings light up one by one."},{"time":"00:50–01:20","narration":"A label points to a part of a picture. A caption is a sentence under the picture.","on_screen":"Label → wing · Caption ↓","visual":"A line draws from 'wing' to a bird's wing; a caption slides in under a camel photo."},{"time":"01:20–01:55","narration":"Hop, hop, hop, says the rabbit in the sun…","on_screen":"Hop, Run, Fly! (poem)","visual":"Layla reads; each animal moves on its line; rhyming words bounce."},{"time":"01:55–02:20","narration":"A poem has a title and lines. Use features to find answers fast!","on_screen":"Find it fast! ⚡","visual":"Saqr zooms to the 'Swim' heading to find the fish."}],"captions_ar":["للنصوص مساعدون! نسميهم سمات النص.","العنوان اسم النص، والعناوين الفرعية أسماء الأجزاء: Run, Fly, Swim, Jump.","البطاقة تشير إلى جزء من الصورة، والتعليق جملة تحت الصورة.","هوب هوب هوب، يقول الأرنب في الشمس…","القصيدة لها عنوان وأسطر. استخدم السمات لتجد الإجابات بسرعة!"],"voice":"Narrator: American English, warm female teacher, speed 0.8. Poem read by Layla: gentle, rhythmic girl voice."},"texts":[{"type":"reading","title":"Hop, Run, Fly!","body":"Hop, hop, hop, says the rabbit in the sun.\n\nRun, run, run, says the horse. This is fun!\n\nSwim, swim, swim, says the fish in the sea.\n\nFly, fly, fly, says the bird in the tree.\n\nWalk, walk, walk, says the camel, big and slow.\n\nJump, jump, jump, says the goat. Up we go!\n\nHow do you move? Show me, one, two, three!","word_count":63,"audio_id":"AUD-RW-L01-U4-LS3-T1","id":"TXT-RW-L01-U4-LS3-1","genre":"poetry (original)","role":"paired","difficulty":"BR–200L","glossary":[{"word":"hop","definition":"a small jump","arabic":"يقفز قفزة صغيرة"},{"word":"Up we go!","definition":"we go up","arabic":"هيا إلى الأعلى!"}]}],"activities":[{"id":"RW-L01-U4-LS3-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Name the text feature.","instructions_ar":"سمِّ سمة النص.","items":[{"q":"The name of the whole text is the ___.","answer":"title","explanation":"The title names the whole text.","explanation_ar":"العنوان اسم النص كله.","options":["caption","label","heading","title"],"dok":1,"skill":"text features","stage":"controlled"},{"q":"*Swim* above one part of the text is a ___.","answer":"heading","explanation":"It names one part.","explanation_ar":"عنوان فرعي.","options":["caption","heading","title","label"],"dok":1,"skill":"text features","stage":"controlled"},{"q":"The word *wing* with a line to a bird's wing is a ___.","answer":"label","explanation":"A label names a part of a picture.","explanation_ar":"بطاقة.","options":["title","heading","label","poem"],"dok":1,"skill":"text features","stage":"controlled"},{"q":"*A camel walks on hot sand.* under a photo is a ___.","answer":"caption","explanation":"A caption is a sentence under a picture.","explanation_ar":"تعليق.","options":["caption","label","heading","title"],"dok":1,"skill":"text features","stage":"controlled"},{"q":"Where do you look to learn about rabbits in *Animals on the Move*?","answer":"under the heading *Jump*","explanation":"The rabbit is in the Jump part.","explanation_ar":"في جزء Jump.","options":["under the heading *Swim*","under the heading *Jump*","in the title only","under the heading *Fly*"],"dok":2,"skill":"using features","stage":"controlled"},{"q":"What does a picture in an information text do?","answer":"shows what the words say","explanation":"Pictures show the facts.","explanation_ar":"الصورة توضح الكلام.","options":["tells the end of a story","gives the page number","shows what the words say","makes the text longer"],"dok":1,"skill":"text features","stage":"controlled"}]},{"id":"RW-L01-U4-LS3-A2","type":"mcq","stage":"guided","instructions":"Guided practice: Read the poem *Hop, Run, Fly!* Choose the answer.","instructions_ar":"اقرأ القصيدة واختر الإجابة.","items":[{"q":"What is the title of the poem?","answer":"Hop, Run, Fly!","explanation":"The title is at the top.","explanation_ar":"العنوان في الأعلى.","options":["Animals on the Move","The Rabbit","Hop, Run, Fly!","Up We Go"],"dok":1,"skill":"title","text_id":"TXT-RW-L01-U4-LS3-1","stage":"guided"},{"q":"Who says *Swim, swim, swim*?","answer":"the fish","explanation":"Line 3.","explanation_ar":"السطر الثالث.","options":["the fish","the bird","the goat","the camel"],"dok":1,"skill":"key details","stage":"guided"},{"q":"Where is the bird?","answer":"in the tree","explanation":"Line 4: in the tree.","explanation_ar":"في الشجرة.","options":["in the sea","in the sun","on a rock","in the tree"],"dok":1,"skill":"key details: where","stage":"guided"},{"q":"How does the camel walk?","answer":"big and slow","explanation":"Line 5: big and slow.","explanation_ar":"كبير وبطيء.","options":["small and fast","big and slow","up and down","in the sea"],"dok":1,"skill":"key details","stage":"guided"},{"q":"Which word rhymes with *sea*?","answer":"tree","explanation":"Sea and tree end with the same sound.","explanation_ar":"sea وtree متناغمتان.","options":["tree","sun","slow","fun"],"dok":1,"skill":"rhyme","stage":"guided"},{"q":"How is the poem different from *Animals on the Move*?","answer":"It has rhyming lines and no headings.","explanation":"Poems have lines and rhymes.","explanation_ar":"القصيدة فيها أسطر متناغمة.","options":["It has headings and captions.","It has no title.","It has rhyming lines and no headings.","It is a note to Grandma."],"dok":2,"skill":"compare features","stage":"guided"}]},{"id":"RW-L01-U4-LS3-A3","type":"organizer","stage":"freer","instructions":"Organizer: Text Feature Hunt. Use *Animals on the Move* and the pictures.","instructions_ar":"رحلة البحث عن سمات النص.","items":[{"q":"Write the title of the information text.","answer":"Animals on the Move","explanation":"The name at the top.","explanation_ar":"الاسم في الأعلى.","dok":1,"skill":"text features","stage":"freer"},{"q":"Write two headings from the information text.","answer":"Fly, Jump","explanation":"Any two headings.","explanation_ar":"أي عنوانين فرعيين.","dok":1,"skill":"text features","stage":"freer"},{"q":"Draw a bird. Add two labels.","answer":"wing, beak","explanation":"Two correct labels.","explanation_ar":"بطاقتان صحيحتان.","dok":1,"skill":"labels","stage":"freer"},{"q":"Write a caption for a picture of a fish.","answer":"A fish swims in the sea.","explanation":"One sentence about the picture.","explanation_ar":"جملة واحدة عن الصورة.","dok":2,"skill":"captions","stage":"freer"}]},{"id":"RW-L01-U4-LS3-A4","type":"open","stage":"production","instructions":"Writing: Make your own animal page.","instructions_ar":"اصنع صفحتك عن حيوان.","items":[{"q":"Write a title for your page.","answer":"The Busy Goat","explanation":"A short name for the page.","explanation_ar":"اسم قصير للصفحة.","dok":1,"skill":"title","stage":"production"},{"q":"Draw your animal. Write two labels.","answer":"horns, legs","explanation":"Two labels with lines.","explanation_ar":"بطاقتان بخطوط.","dok":1,"skill":"labels","stage":"production"},{"q":"Write a caption under your picture.","answer":"The goat jumps on rocks.","explanation":"One sentence.","explanation_ar":"جملة واحدة.","dok":2,"skill":"captions","stage":"production"},{"q":"Write a heading and one fact under it.","answer":"Food – A goat eats grass.","explanation":"Heading + fact.","explanation_ar":"عنوان فرعي + حقيقة.","dok":2,"skill":"headings","stage":"production"}]},{"id":"RW-L01-U4-LS3-TR-1","type":"timed_reading","instructions":"Timed reading: Read \"Hop, Run, Fly!\" aloud or silently. Try to finish in the time.","instructions_ar":"اقرأ النص وحاول أن تنهيه في الوقت المحدد.","items":[{"q":"Read “Hop, Run, Fly!”.","answer":"63 words","title":"Hop, Run, Fly!","body":"Hop, hop, hop, says the rabbit in the sun.\n\nRun, run, run, says the horse. This is fun!\n\nSwim, swim, swim, says the fish in the sea.\n\nFly, fly, fly, says the bird in the tree.\n\nWalk, walk, walk, says the camel, big and slow.\n\nJump, jump, jump, says the goat. Up we go!\n\nHow do you move? Show me, one, two, three!","words":63,"limit":109}],"time_limit_sec":109},{"id":"RW-L01-U4-LS3-ORG","type":"organizer","organizer":"Text Feature Hunt","instructions":"Organizer: Find each feature. Write where it is and what it tells you.","items":[{"q":"Title – where? what does it tell?","answer":"top of the page: Animals on the Move – how animals move"},{"q":"Heading – where? what does it tell?","answer":"above a part: Swim – animals that swim"},{"q":"Label – where? what does it tell?","answer":"on the bird picture: wing – the part for flying"},{"q":"Caption – where? what does it tell?","answer":"under the camel picture: A camel walks on hot sand."}]}],"game":{"name":"Feature Detective Race","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Tap-the-feature: the app says \"Tap the caption!\"; the child taps the right part of a page. Correct = the feature glows with its name. 10 calls, getting faster.","Pairs get the same page.","The teacher calls a feature: \"Caption!\"","Pairs put a sticker on it and raise hands.","First correct pair = 2 points; other correct pairs = 1 point.","Play 10 calls."],"data":[]},"exit_quiz":[{"q":"Text features help you ___.","answer":"find information fast","explanation":"Features help us find things.","explanation_ar":"السمات تساعدنا على إيجاد المعلومات.","options":["write a long story","find information fast","sing a song","draw a map"],"dok":1,"skill":"strategy"},{"q":"A caption is ___.","answer":"a sentence under a picture","explanation":"Captions go under pictures.","explanation_ar":"التعليق تحت الصورة.","options":["the name of the whole text","a rhyming word","a sentence under a picture","a page number"],"dok":1,"skill":"text features"},{"q":"A label is ___.","answer":"a word with a line to part of a picture","explanation":"Labels name parts of pictures.","explanation_ar":"البطاقة تسمي جزءًا من الصورة.","options":["a long story","the last line of a poem","a word with a line to part of a picture","a question"],"dok":1,"skill":"text features"},{"q":"In the poem, who says *This is fun!*?","answer":"the horse","explanation":"Line 2: says the horse. This is fun!","explanation_ar":"الحصان.","options":["the horse","the fish","the goat","the camel"],"dok":1,"skill":"key details"},{"q":"Which word rhymes with *go*?","answer":"slow","explanation":"Go and slow rhyme.","explanation_ar":"go وslow متناغمتان.","options":["sun","slow","sea","fun"],"dok":1,"skill":"rhyme"},{"q":"In *Animals on the Move*, what heading tells about birds?","answer":"Fly","explanation":"Birds are in the Fly part.","explanation_ar":"الطيور في جزء Fly.","options":["Run","Swim","Jump","Fly"],"dok":2,"skill":"using features"},{"q":"Which feature does the poem have?","answer":"a title","explanation":"The poem has a title and lines.","explanation_ar":"القصيدة لها عنوان.","options":["a title","headings","captions","labels"],"dok":2,"skill":"compare features"},{"q":"*The camel is big and slow.* *Slow* is the opposite of ___.","answer":"fast","explanation":"Slow ≠ fast.","explanation_ar":"slow عكس fast.","options":["big","fast","small","happy"],"dok":1,"skill":"vocabulary"},{"q":"You want to know about fish. What is the fastest way?","answer":"Look for the heading *Swim*.","explanation":"Headings show where to look.","explanation_ar":"العناوين الفرعية تدلّك.","options":["Read every word from the start.","Look at the page number.","Close the book.","Look for the heading *Swim*."],"dok":2,"skill":"using features"},{"q":"Why does the poet write *Hop, hop, hop*?","answer":"to sound like the rabbit moving","explanation":"Repeating the word shows the movement.","explanation_ar":"التكرار يصوّر حركة الأرنب.","options":["to give a fact about food","to tell the title","to show a mistake","to sound like the rabbit moving"],"dok":3,"skill":"author's craft"}],"images":[{"id":"IMG-RW-L01-U4-LS3-V01","prompt":"Picture for the word 'heading': a page with a bold heading above a short paragraph"},{"id":"IMG-RW-L01-U4-LS3-V02","prompt":"Picture for the word 'caption': a photo of a camel with a short line of text below"},{"id":"IMG-RW-L01-U4-LS3-V03","prompt":"Picture for the word 'label': a bird picture with a line pointing to its wing"},{"id":"IMG-RW-L01-U4-LS3-V04","prompt":"Picture for the word 'feature': a magnifying glass over a page showing a title, a picture and a label"},{"id":"IMG-RW-L01-U4-LS3-V05","prompt":"Picture for the word 'hop': a small bird hopping on grass"},{"id":"IMG-RW-L01-U4-LS3-V06","prompt":"Picture for the word 'sea': blue sea with small waves and a boat"},{"id":"IMG-RW-L01-U4-LS3-V07","prompt":"Picture for the word 'slow': a turtle walking slowly"},{"id":"IMG-RW-L01-U4-LS3-01","prompt":"Animals move around Layla as she reads the poem."},{"id":"IMG-RW-L01-U4-LS3-02","prompt":"A sample page showing a title, a heading, a picture, labels and a caption."},{"id":"IMG-RW-L01-U4-LS3-03","prompt":"A toolbox with tools for text features."}],"audio":[{"id":"AUD-RW-L01-U4-LS3-V01","script":"heading. The heading says *Swim*."},{"id":"AUD-RW-L01-U4-LS3-V02","script":"caption. Read the caption under the photo."},{"id":"AUD-RW-L01-U4-LS3-V03","script":"label. The label says *wing*."},{"id":"AUD-RW-L01-U4-LS3-V04","script":"feature. A title is a text feature."},{"id":"AUD-RW-L01-U4-LS3-V05","script":"hop. The bird hops on the grass."},{"id":"AUD-RW-L01-U4-LS3-V06","script":"sea. The Red Sea is beautiful."},{"id":"AUD-RW-L01-U4-LS3-V07","script":"slow. The turtle is slow."},{"id":"AUD-RW-L01-U4-LS3-T1","script":"Hop, hop, hop, says the rabbit in the sun. Run, run, run, says the horse. This is fun! Swim, swim, swim, says the fish in the sea. Fly, fly, fly, says the bird in the tree. Walk, walk, walk, says the camel, big and slow. Jump, jump, jump, says the goat. Up we go! How do you move? Show me, one, two, three!"},{"id":"AUD-RW-L01-U4-LS3-VID","script":"Texts have helpers! They are called text features. The title is the name of the text. Headings are names of parts: Run, Fly, Swim, Jump. A label points to a part of a picture. A caption is a sentence under the picture. Hop, hop, hop, says the rabbit in the sun… A poem has a title and lines. Use features to find answers fast!"}]},{"id":"RW-L01-U4-LS4","title":"Writing Skill: Describing words: big, small, fast, slow","lesson_type":"writing_skill","objectives":["use describing words for size, speed, color and feel (big, small, fast, slow, soft)","put a describing word before a naming word (a big camel) or after is (The camel is big)","write sentences describing an animal"],"objectives_ar":["استخدام الكلمات الوصفية للحجم والسرعة واللون والملمس.","وضع الكلمة الوصفية قبل الاسم أو بعد is.","كتابة جمل تصف حيوانًا."],"success_criteria":["I can find describing words.","I can put the describing word before the naming word.","I can describe an animal in sentences."],"success_criteria_ar":["أستطيع إيجاد الكلمات الوصفية.","أستطيع وضع الكلمة الوصفية قبل الاسم.","أستطيع وصف حيوان في جمل."],"map_area":"Language Usage: Write, Revise Texts for Purpose and Audience (cross-strand)","vocabulary":[{"word":"describing word","pos":"noun","ipa":"/dɪˈskraɪbɪŋ wɝd/","definition":"a word that tells what something is like (an adjective)","arabic":"كلمة وصفية (صفة)","example":"*Big* is a describing word.","image_id":"IMG-RW-L01-U4-LS4-V01","audio_id":"AUD-RW-L01-U4-LS4-V01","tier":"core"},{"word":"fast","pos":"adjective","ipa":"/fæst/","definition":"moving quickly","arabic":"سريع","example":"The horse is fast.","image_id":"IMG-RW-L01-U4-LS4-V02","audio_id":"AUD-RW-L01-U4-LS4-V02","tier":"core"},{"word":"soft","pos":"adjective","ipa":"/sɔft/","definition":"nice to touch; not hard","arabic":"ناعم","example":"The rabbit has soft fur.","image_id":"IMG-RW-L01-U4-LS4-V03","audio_id":"AUD-RW-L01-U4-LS4-V03","tier":"core"},{"word":"fur","pos":"noun","ipa":"/fɝ/","definition":"the soft hair on some animals","arabic":"فرو","example":"The cat's fur is white.","image_id":"IMG-RW-L01-U4-LS4-V04","audio_id":"AUD-RW-L01-U4-LS4-V04","tier":"core"},{"word":"tiny","pos":"adjective","ipa":"/ˈtaɪni/","definition":"very, very small","arabic":"صغير جدًا","example":"An ant is tiny.","image_id":"IMG-RW-L01-U4-LS4-V05","audio_id":"AUD-RW-L01-U4-LS4-V05","tier":"core"},{"word":"beautiful","pos":"adjective","ipa":"/ˈbjutəfəl/","definition":"very nice to look at","arabic":"جميل","example":"The bird has beautiful feathers.","image_id":"IMG-RW-L01-U4-LS4-V06","audio_id":"AUD-RW-L01-U4-LS4-V06","tier":"core"},{"word":"color","pos":"noun","ipa":"/ˈkʌlər/","definition":"red, blue, green and yellow are colors","arabic":"لون","example":"What color is the duck?","image_id":"IMG-RW-L01-U4-LS4-V07","audio_id":"AUD-RW-L01-U4-LS4-V07","tier":"core"}],"explanation":{"text":"A **describing word** tells what something is like: **size** (big, small, tiny), **speed** (fast, slow), **color** (white, brown) and **feel** (soft). Later you will call it an **adjective**.\n\nPut the describing word **before** the naming word: *a **big** camel*, *a **white** cat*. (In Arabic it comes after: جمل كبير.)\n\nOr put it **after is/are**: *The camel **is** big. The ducks **are** small.*\n\nDescribing words never take **-s**: *two big camels* (not *bigs*).","examples":["a **big** camel → The camel is **big**.","a **small** rabbit → The rabbit is **small**.","a **fast** horse → The horse is **fast**.","a **slow** camel → The camel is **slow**.","**soft** fur → The fur is **soft**.","a **tiny** fish → The fish is **tiny**.","a **white** cat with **green** eyes","**two big** goats (no -s on big)","a **beautiful** bird with **long** wings"],"common_errors":["✗ a camel big → ✓ a big camel (In English the describing word comes **before** the naming word.)","✗ two bigs horses → ✓ two big horses (No **-s** on describing words.)","✗ The cat soft. → ✓ The cat is soft. (Use **is** before the describing word.)","✗ The horse is fastly. → ✓ The horse is fast. (Say **fast**.)","✗ a fish orange → ✓ an orange fish (Color before the naming word; **an** before a vowel sound.)","✗ The rabbit very soft. → ✓ The rabbit is very soft. (Do not forget **is**.)"],"arabic":"الكلمة الوصفية (الصفة) تخبرنا كيف يبدو الشيء: الحجم مثل big، والسرعة مثل fast، واللون مثل white، والملمس مثل soft.\n\nفي الإنجليزية نضع الصفة قبل الاسم: a big camel، بينما في العربية تأتي بعد الاسم: جمل كبير.\n\nأو نضعها بعد is/are: The camel is big.\n\nالصفة لا تُجمع ولا نضيف لها s: two big camels."},"video":{"script":[{"time":"00:00–00:15","narration":"Describing words make pictures better!","on_screen":"Describing words ✨","visual":"A grey outline of a cat; when 'white', 'small' and 'green eyes' appear, the cat fills with color."},{"time":"00:15–00:45","narration":"Big or small? A big camel. A small rabbit.","on_screen":"big · small","visual":"A giant camel and a tiny rabbit side by side; the words sit before the animal names."},{"time":"00:45–01:10","narration":"Fast or slow? A fast horse. A slow camel.","on_screen":"fast · slow","visual":"A horse zooms past; a camel walks slowly; the snail-speed camel winks."},{"time":"01:10–01:40","narration":"Careful! In Arabic we say 'camel big'. In English we say 'big camel'. Swap!","on_screen":"camel big ✗ → big camel ✓","visual":"The words 'camel' and 'big' swap places with a whoosh."},{"time":"01:40–02:10","narration":"Layla describes her cat: She is small and white. She has soft fur and big green eyes.","on_screen":"Layla's cat, Qamar","visual":"Layla holds Qamar; each describing word glows as she reads."},{"time":"02:10–02:30","narration":"Now describe YOUR favorite animal!","on_screen":"Describe it!","visual":"Saqr points to a blank animal outline waiting for color."}],"captions_ar":["الكلمات الوصفية تجعل الصورة أجمل!","كبير أم صغير؟ جمل كبير. أرنب صغير.","سريع أم بطيء؟ حصان سريع. جمل بطيء.","انتبه! بالعربية نقول جمل كبير، وبالإنجليزية big camel. بدّل المكان!","ليلى تصف قطتها: صغيرة وبيضاء، فروها ناعم وعيناها خضراوان كبيرتان.","والآن صف حيوانك المفضل!"],"voice":"Narrator: American English, warm female teacher, speed 0.8. Layla: soft, kind girl voice. A gentle 'swap' sound when words change places."},"texts":[{"type":"model","title":"My Cat, Qamar (from Layla's Notebook)","body":"I have a cat. Her name is Qamar. She is small and white. She has soft fur and big green eyes.\n\nQamar is fast! She can jump on the garden wall. At night, she is slow and sleepy.","word_count":38,"audio_id":"AUD-RW-L01-U4-LS4-T1","id":"TXT-RW-L01-U4-LS4-1","genre":"model text","role":"model","difficulty":"BR–200L","glossary":[],"annotations":["**small**, **white** – describing words after *is* tell what Qamar is like.","**soft** fur, **big green** eyes – describing words come BEFORE the naming word.","**fast** / **slow** – opposite describing words show how she moves.","**garden** wall – a naming word can describe too!","Qamar – a special name with a capital letter."]}],"activities":[{"id":"RW-L01-U4-LS4-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Choose the describing word.","instructions_ar":"اختر الكلمة الوصفية.","items":[{"q":"Which is a describing word in *The tiny bird sings*?","answer":"tiny","explanation":"Tiny tells what the bird is like.","explanation_ar":"tiny صفة.","options":["bird","sings","The","tiny"],"dok":1,"skill":"describing words","stage":"controlled"},{"q":"Which is a describing word in *A brown goat eats grass*?","answer":"brown","explanation":"Brown is a color word.","explanation_ar":"brown صفة لون.","options":["goat","eats","brown","grass"],"dok":1,"skill":"describing words","stage":"controlled"},{"q":"Which word is the opposite of *fast*?","answer":"slow","explanation":"Slow is the opposite of fast.","explanation_ar":"slow عكس fast.","options":["big","slow","soft","tiny"],"dok":1,"skill":"opposites","stage":"controlled"},{"q":"Which word tells how fur feels?","answer":"soft","explanation":"Soft tells how it feels.","explanation_ar":"soft تصف الملمس.","options":["fast","soft","slow","tall"],"dok":1,"skill":"describing words","stage":"controlled"},{"q":"Which word means *very, very small*?","answer":"tiny","explanation":"Tiny = very small.","explanation_ar":"tiny صغير جدًا.","options":["tiny","big","slow","beautiful"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"Which phrase is in the right order?","answer":"a white horse","explanation":"Describing word before the naming word.","explanation_ar":"الصفة قبل الاسم.","options":["a horse white","horse a white","a white horse","white a horse"],"dok":2,"skill":"word order","stage":"controlled"}]},{"id":"RW-L01-U4-LS4-A2","type":"open","stage":"guided","instructions":"Guided practice: Swap the words! Write the describing word before the naming word.","instructions_ar":"بدّل الكلمات: اكتب الصفة قبل الاسم.","items":[{"q":"a camel big","answer":"a big camel","explanation":"big before camel.","explanation_ar":"big قبل camel.","dok":1,"skill":"word order","stage":"guided"},{"q":"a rabbit soft","answer":"a soft rabbit","explanation":"soft before rabbit.","explanation_ar":"soft قبل rabbit.","dok":1,"skill":"word order","stage":"guided"},{"q":"a duck yellow","answer":"a yellow duck","explanation":"yellow before duck.","explanation_ar":"yellow قبل duck.","dok":1,"skill":"word order","stage":"guided"},{"q":"two horses fast","answer":"two fast horses","explanation":"fast before horses; no -s on fast.","explanation_ar":"fast قبل horses.","dok":2,"skill":"word order","stage":"guided"},{"q":"a bird beautiful","answer":"a beautiful bird","explanation":"beautiful before bird.","explanation_ar":"beautiful قبل bird.","dok":1,"skill":"word order","stage":"guided"},{"q":"an ant tiny","answer":"a tiny ant","explanation":"tiny before ant; a before tiny.","explanation_ar":"tiny قبل ant.","dok":2,"skill":"word order","stage":"guided"}]},{"id":"RW-L01-U4-LS4-A3","type":"open","stage":"freer","instructions":"Freer practice: Complete with a describing word that makes sense.","instructions_ar":"أكمل بكلمة وصفية مناسبة.","items":[{"q":"The camel is ______ and ______.","answer":"The camel is big and slow.","explanation":"Two describing words.","explanation_ar":"صفتان.","dok":2,"skill":"describing","stage":"freer"},{"q":"I see a ______ fish in the sea.","answer":"I see an orange fish in the sea.","explanation":"A color or size word.","explanation_ar":"صفة لون أو حجم.","dok":2,"skill":"describing","stage":"freer"},{"q":"My cat has ______ fur.","answer":"My cat has soft fur.","explanation":"A feel or color word.","explanation_ar":"صفة ملمس أو لون.","dok":2,"skill":"describing","stage":"freer"},{"q":"The horse is very ______!","answer":"The horse is very fast!","explanation":"A speed word.","explanation_ar":"صفة سرعة.","dok":2,"skill":"describing","stage":"freer"}]},{"id":"RW-L01-U4-LS4-A4","type":"open","stage":"production","instructions":"Writing: Describe an animal. Write 4 sentences.","instructions_ar":"صف حيوانًا في 4 جمل.","items":[{"q":"Write the animal and its size.","answer":"A rabbit is small.","explanation":"Animal + is + size word.","explanation_ar":"حيوان + is + حجم.","dok":1,"skill":"describing","stage":"production"},{"q":"Write its color.","answer":"It is white.","explanation":"It is + color.","explanation_ar":"It is + لون.","dok":1,"skill":"describing","stage":"production"},{"q":"Write how it feels or what it has.","answer":"It has soft fur and long ears.","explanation":"It has + describing word + naming word.","explanation_ar":"It has + صفة + اسم.","dok":2,"skill":"describing","stage":"production"},{"q":"Write how it moves. Use fast or slow.","answer":"It is fast. It can jump.","explanation":"fast/slow + can.","explanation_ar":"fast/slow + can.","dok":2,"skill":"describing","stage":"production"}]}],"game":{"name":"Guess My Animal","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Build-a-clue: the child chooses three describing-word tiles for a hidden animal; a robot friend guesses. If the robot guesses right, the child gets a star. Then the roles switch: the robot gives clues and the child guesses.","A student picks an animal card secretly.","The student gives three clues with describing words (\"It is big. It is brown. It is slow.\").","The team guesses after each clue.","Guess after clue 1 = 3 points; clue 2 = 2 points; clue 3 = 1 point.","Next student picks a card."],"data":[]},"exit_quiz":[{"q":"A describing word tells ___.","answer":"what something is like","explanation":"Describing words tell what things are like.","explanation_ar":"الصفة تخبرنا كيف يبدو الشيء.","options":["what something is like","who does an action","where a story is","the end of a sentence"],"dok":1,"skill":"rule"},{"q":"Which phrase is correct?","answer":"a small rabbit","explanation":"Describing word before naming word.","explanation_ar":"الصفة قبل الاسم.","options":["a rabbit small","a small rabbit","rabbit a small","small rabbit a"],"dok":1,"skill":"word order"},{"q":"Which sentence about the tiny fish is correct?","answer":"The fish is tiny.","explanation":"The fish + is + tiny.","explanation_ar":"The fish is tiny.","options":["The fish tiny.","The tiny is fish.","Fish the tiny is.","The fish is tiny."],"dok":1,"skill":"sentence"},{"q":"Which group has only describing words?","answer":"big, soft, fast","explanation":"All three describe.","explanation_ar":"كلها صفات.","options":["cat, goat, duck","run, jump, swim","big, soft, fast","Qamar, Layla, Sami"],"dok":1,"skill":"describing words"},{"q":"Which phrase about three goats is correct?","answer":"three brown goats","explanation":"No -s on brown; goats has -s.","explanation_ar":"لا s على الصفة.","options":["three browns goats","three goats browns","three brown goat","three brown goats"],"dok":2,"skill":"agreement"},{"q":"In Layla's model, what color are Qamar's eyes?","answer":"green","explanation":"Text: big green eyes.","explanation_ar":"عيناها خضراوان.","options":["blue","brown","black","green"],"dok":1,"skill":"key details"},{"q":"In Layla's model, when is Qamar slow?","answer":"at night","explanation":"Text: At night, she is slow and sleepy.","explanation_ar":"في الليل.","options":["at night","in the morning","at school","at lunch"],"dok":1,"skill":"key details"},{"q":"Which describing word best fits a horse that wins a race?","answer":"fast","explanation":"Winners are fast.","explanation_ar":"الفائز سريع.","options":["slow","fast","tiny","soft"],"dok":2,"skill":"word choice"},{"q":"How do you fix *The camel very big*?","answer":"The camel is very big.","explanation":"Add is.","explanation_ar":"أضف is.","options":["The camel is very big.","The very camel big.","The camel big very.","Camel the very big."],"dok":2,"skill":"editing"},{"q":"Which sentence gives the BEST picture?","answer":"The tiny white rabbit has soft fur.","explanation":"It has three describing words.","explanation_ar":"فيها ثلاث صفات.","options":["The rabbit.","It is an animal.","The tiny white rabbit has soft fur.","I see it."],"dok":3,"skill":"word choice"}],"images":[{"id":"IMG-RW-L01-U4-LS4-V01","prompt":"Picture for the word 'describing word': a big balloon and a small balloon with word cards"},{"id":"IMG-RW-L01-U4-LS4-V02","prompt":"Picture for the word 'fast': a horse running with motion lines"},{"id":"IMG-RW-L01-U4-LS4-V03","prompt":"Picture for the word 'soft': a hand stroking a fluffy rabbit"},{"id":"IMG-RW-L01-U4-LS4-V04","prompt":"Picture for the word 'fur': close-up of white cat fur"},{"id":"IMG-RW-L01-U4-LS4-V05","prompt":"Picture for the word 'tiny': a tiny ant next to a pencil tip"},{"id":"IMG-RW-L01-U4-LS4-V06","prompt":"Picture for the word 'beautiful': a bird with bright colorful feathers"},{"id":"IMG-RW-L01-U4-LS4-V07","prompt":"Picture for the word 'color': a row of color dots"},{"id":"IMG-RW-L01-U4-LS4-01","prompt":"Layla holds her small white cat, Qamar."},{"id":"IMG-RW-L01-U4-LS4-02","prompt":"Two tiles swapping places to show word order."},{"id":"IMG-RW-L01-U4-LS4-03","prompt":"Pictures for size, speed, color and feel."}],"audio":[{"id":"AUD-RW-L01-U4-LS4-V01","script":"describing word. *Big* is a describing word."},{"id":"AUD-RW-L01-U4-LS4-V02","script":"fast. The horse is fast."},{"id":"AUD-RW-L01-U4-LS4-V03","script":"soft. The rabbit has soft fur."},{"id":"AUD-RW-L01-U4-LS4-V04","script":"fur. The cat's fur is white."},{"id":"AUD-RW-L01-U4-LS4-V05","script":"tiny. An ant is tiny."},{"id":"AUD-RW-L01-U4-LS4-V06","script":"beautiful. The bird has beautiful feathers."},{"id":"AUD-RW-L01-U4-LS4-V07","script":"color. What color is the duck?"},{"id":"AUD-RW-L01-U4-LS4-T1","script":"I have a cat. Her name is Qamar. She is small and white. She has soft fur and big green eyes. Qamar is fast! She can jump on the garden wall. At night, she is slow and sleepy."},{"id":"AUD-RW-L01-U4-LS4-VID","script":"Describing words make pictures better! Big or small? A big camel. A small rabbit. Fast or slow? A fast horse. A slow camel. Careful! In Arabic we say 'camel big'. In English we say 'big camel'. Swap! Layla describes her cat: She is small and white. She has soft fur and big green eyes. Now describe YOUR favorite animal!"}]},{"id":"RW-L01-U4-LS5","title":"Writing Workshop: My Favorite Animal","lesson_type":"writing_workshop","objectives":["plan an animal fact page with a labelled picture","write 4 fact sentences with It is…, It has…, It can… and It eats…, using describing words","edit for describing-word order, capitals and periods, and publish on the class Animal Wall"],"objectives_ar":["التخطيط لصفحة حقائق عن حيوان مع صورة عليها بطاقات.","كتابة 4 جمل حقائق باستخدام It is وIt has وIt can وIt eats مع الصفات.","تدقيق ترتيب الصفات والحروف الكبيرة والنقاط والنشر على جدار الحيوانات."],"success_criteria":["I can draw and label my favorite animal.","I can write 4 fact sentences about it.","I can use describing words in the right place."],"success_criteria_ar":["أستطيع رسم حيواني المفضل ووضع البطاقات.","أستطيع كتابة 4 جمل حقائق عنه.","أستطيع استخدام الصفات في مكانها الصحيح."],"map_area":"Language Usage: Write, Revise Texts for Purpose and Audience (cross-strand)","vocabulary":[{"word":"tail","pos":"noun","ipa":"/teɪl/","definition":"the long part at the back of an animal","arabic":"ذيل","example":"The cat has a long tail.","image_id":"IMG-RW-L01-U4-LS5-V01","audio_id":"AUD-RW-L01-U4-LS5-V01","tier":"core"},{"word":"ears","pos":"noun","ipa":"/ɪrz/","definition":"the parts of the head you hear with","arabic":"أذنان","example":"A rabbit has long ears.","image_id":"IMG-RW-L01-U4-LS5-V02","audio_id":"AUD-RW-L01-U4-LS5-V02","tier":"core"},{"word":"neck","pos":"noun","ipa":"/nɛk/","definition":"the part between the head and the body","arabic":"رقبة","example":"A camel has a long neck.","image_id":"IMG-RW-L01-U4-LS5-V03","audio_id":"AUD-RW-L01-U4-LS5-V03","tier":"core"},{"word":"food","pos":"noun","ipa":"/fud/","definition":"what animals and people eat","arabic":"طعام","example":"Grass is food for goats.","image_id":"IMG-RW-L01-U4-LS5-V04","audio_id":"AUD-RW-L01-U4-LS5-V04","tier":"core"},{"word":"grass","pos":"noun","ipa":"/ɡræs/","definition":"green plants that cover the ground","arabic":"عشب","example":"The horse eats grass.","image_id":"IMG-RW-L01-U4-LS5-V05","audio_id":"AUD-RW-L01-U4-LS5-V05","tier":"core"},{"word":"seeds","pos":"noun","ipa":"/sidz/","definition":"small parts of plants that birds eat","arabic":"بذور","example":"Birds eat seeds.","image_id":"IMG-RW-L01-U4-LS5-V06","audio_id":"AUD-RW-L01-U4-LS5-V06","tier":"core"},{"word":"farm","pos":"noun","ipa":"/fɑrm/","definition":"a place with animals and plants for food","arabic":"مزرعة","example":"We see goats on the farm.","image_id":"IMG-RW-L01-U4-LS5-V07","audio_id":"AUD-RW-L01-U4-LS5-V07","tier":"core"}],"explanation":{"text":"A **fact page** gives true information about one animal. It has a **title**, a **picture with labels** and **fact sentences**.\n\nUse four sentence starters: **It is…** (size, color) · **It has…** (body parts) · **It can…** (how it moves) · **It eats…** (food).\n\nAdd **describing words** in the right place: *It has **long** ears.*","examples":["Title: **The Arabian Horse**","**It is** big and fast.","**It is** white or brown.","**It has** a long tail and strong legs.","**It can** run very fast.","**It eats** grass and hay.","Labels on the picture: **tail**, **legs**, **ears**.","Bird page: **It has** two wings. **It eats** seeds.","Camel page: **It has** a long neck. **It can** walk in the desert."],"common_errors":["✗ It is have a long tail. → ✓ It has a long tail. (Use **has**, not *is have*.)","✗ It can runs fast. → ✓ It can run fast. (After can, the plain word.)","✗ It eat grass. → ✓ It eats grass. (With **it**, add **-s**.)","✗ It has ears long. → ✓ It has long ears. (Describing word before the naming word.)","✗ The horse it is fast. → ✓ The horse is fast. / It is fast. (One subject only.)","✗ it is big → ✓ It is big. (Capital I and a period.)"],"arabic":"صفحة الحقائق تعطي معلومات صحيحة عن حيوان واحد: لها عنوان، وصورة عليها بطاقات، وجمل حقائق.\n\nاستخدم أربع بدايات: It is (الحجم واللون)، It has (أجزاء الجسم)، It can (الحركة)، It eats (الطعام).\n\nضع الصفات في مكانها الصحيح قبل الاسم: It has long ears.\n\nانتبه: نقول It eats بإضافة s، وIt can run دون s."},"video":{"script":[{"time":"00:00–00:15","narration":"Omar loves horses. He makes a fact page!","on_screen":"My Favorite Animal","visual":"Omar holds a microphone next to a horse picture: 'Omar Reports!'"},{"time":"00:15–00:45","narration":"Plan: draw the horse. Add labels: tail, legs, ears.","on_screen":"1 Plan – picture + labels","visual":"Label lines draw onto the horse picture."},{"time":"00:45–01:20","narration":"Draft: It is big and fast. It has a long tail. It can run very fast. It eats grass.","on_screen":"2 Draft – It is · It has · It can · It eats","visual":"Four sentence starters light up in four colors as Omar reads."},{"time":"01:20–01:45","narration":"Revise: It has a tail… It has a long, beautiful tail!","on_screen":"3 Revise ➕ long, beautiful","visual":"Describing words slide into place before 'tail'."},{"time":"01:45–02:10","narration":"Edit: It eats – add s! It can run – no s! Capitals and periods – check!","on_screen":"4 Edit ✔","visual":"An 's' pops onto 'eat'; a check mark appears after each sentence."},{"time":"02:10–02:40","narration":"Publish: put your page on the Animal Wall. Tell a friend one fact!","on_screen":"5 Publish 🐾","visual":"The class Animal Wall fills with pages: camel, rabbit, duck, horse."}],"captions_ar":["عمر يحب الخيول. سيصنع صفحة حقائق!","خطِّط: ارسم الحصان وأضف البطاقات: ذيل، أرجل، أذنان.","المسودة: إنه كبير وسريع. له ذيل طويل. يستطيع الجري بسرعة كبيرة. يأكل العشب.","التحسين: له ذيل… له ذيل طويل جميل!","التدقيق: It eats بإضافة s، وIt can run بدون s. حروف كبيرة ونقاط.","النشر: ضع صفحتك على جدار الحيوانات وأخبر صديقك بحقيقة!"],"voice":"Narrator: American English, warm female teacher, speed 0.8. Omar: excited boy voice presenting his page like a reporter."},"texts":[],"activities":[{"id":"RW-L01-U4-LS5-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Choose the best word.","instructions_ar":"اختر أفضل كلمة.","items":[{"q":"A camel has a long ___.","answer":"neck","explanation":"Camels have long necks.","explanation_ar":"للجمل رقبة طويلة.","options":["seeds","farm","food","neck"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"Birds eat ___.","answer":"seeds","explanation":"Birds eat seeds.","explanation_ar":"الطيور تأكل البذور.","options":["rocks","tails","seeds","farms"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"A goat lives on a ___.","answer":"farm","explanation":"Goats live on farms.","explanation_ar":"الماعز يعيش في المزرعة.","options":["neck","farm","seed","tail"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"Which starter tells how an animal moves?","answer":"It can…","explanation":"It can tells what it can do.","explanation_ar":"It can للحركة.","options":["It eats…","It is…","It can…","It has…"],"dok":1,"skill":"sentence starters","stage":"controlled"},{"q":"Which starter tells body parts?","answer":"It has…","explanation":"It has tells parts.","explanation_ar":"It has لأجزاء الجسم.","options":["It has…","It can…","It eats…","It moves…"],"dok":1,"skill":"sentence starters","stage":"controlled"},{"q":"Which 'It eats' sentence is written correctly?","answer":"It eats grass.","explanation":"It + eats.","explanation_ar":"It eats.","options":["It eat grass.","It eats grass.","It is eat grass.","It eats grasses grass."],"dok":2,"skill":"sentence check","stage":"controlled"}]},{"id":"RW-L01-U4-LS5-A2","type":"sequence","stage":"guided","instructions":"Put in order: Put the words in order.","instructions_ar":"رتّب الكلمات.","items":[{"q":"Build an 'It is' sentence about a camel.","answer":"It is big and brown.","explanation":"It is big and brown.","explanation_ar":"إنه كبير وبني.","stage":"guided","parts":["and","is","big","brown.","It"],"target":["It","is","big","and","brown."]},{"q":"Build an 'It has' sentence about a tail.","answer":"It has a long tail.","explanation":"Describing word before tail.","explanation_ar":"الصفة قبل tail.","stage":"guided","parts":["has","It","long","a","tail."],"target":["It","has","a","long","tail."]},{"q":"Build an 'It can' sentence about running.","answer":"It can run very fast.","explanation":"It can + plain word.","explanation_ar":"It can + فعل.","stage":"guided","parts":["very","fast.","It","run","can"],"target":["It","can","run","very","fast."]},{"q":"Build an 'It eats' sentence about a bird.","answer":"It eats seeds.","explanation":"It eats + food.","explanation_ar":"It eats + طعام.","stage":"guided","parts":["It","seeds.","eats"],"target":["It","eats","seeds."]},{"q":"Build a sentence about a rabbit's ears.","answer":"A rabbit has long ears.","explanation":"long before ears.","explanation_ar":"long قبل ears.","stage":"guided","parts":["A","has","ears.","rabbit","long"],"target":["A","rabbit","has","long","ears."]},{"q":"Build a sentence about where a goat lives.","answer":"The goat lives on a farm.","explanation":"The goat lives on a farm.","explanation_ar":"يعيش الماعز في مزرعة.","stage":"guided","parts":["lives","a","farm.","on","goat","The"],"target":["The","goat","lives","on","a","farm."]}]},{"id":"RW-L01-U4-LS5-A3","type":"open","stage":"freer","instructions":"Freer practice: Choose an animal. Complete the fact sentences.","instructions_ar":"اختر حيوانًا وأكمل جمل الحقائق.","items":[{"q":"It is ______.","answer":"It is small and white.","explanation":"Size or color words.","explanation_ar":"صفات حجم أو لون.","dok":1,"skill":"facts","stage":"freer"},{"q":"It has ______.","answer":"It has long ears.","explanation":"A body part with a describing word.","explanation_ar":"جزء من الجسم مع صفة.","dok":2,"skill":"facts","stage":"freer"},{"q":"It can ______.","answer":"It can jump.","explanation":"A movement word.","explanation_ar":"كلمة حركة.","dok":1,"skill":"facts","stage":"freer"},{"q":"It eats ______.","answer":"It eats carrots.","explanation":"A food word.","explanation_ar":"كلمة طعام.","dok":1,"skill":"facts","stage":"freer"}]},{"id":"RW-L01-U4-LS5-A4","type":"writing","stage":"production","instructions":"Writing: Make your fact page. Then edit and publish.","instructions_ar":"اصنع صفحة الحقائق ثم دققها وانشرها.","items":[{"q":"Write your title.","answer":"The Duck","explanation":"The animal's name.","explanation_ar":"اسم الحيوان.","dok":1,"skill":"writing","stage":"production"},{"q":"Write your It is and It has sentences.","answer":"It is small and yellow. It has two wings.","explanation":"Two sentences.","explanation_ar":"جملتان.","dok":2,"skill":"writing","stage":"production"},{"q":"Write your It can and It eats sentences.","answer":"It can swim and fly. It eats seeds and plants.","explanation":"Two sentences.","explanation_ar":"جملتان.","dok":2,"skill":"writing","stage":"production"},{"q":"What fact did your partner learn from your page?","answer":"He learned that ducks can fly.","explanation":"One fact.","explanation_ar":"حقيقة واحدة.","dok":2,"skill":"sharing","stage":"production","_w":{"checklist":[],"min":null,"max":null}}]},{"id":"RW-L01-U4-LS5-ORG","type":"organizer","organizer":"Animal Fact Plan","instructions":"Organizer: Draw your animal in the middle. Write one fact in each box.","items":[{"q":"It is… (size, color)","answer":"big and brown"},{"q":"It has… (body parts)","answer":"a long neck and a hump"},{"q":"It can… (how it moves)","answer":"walk in the desert"},{"q":"It eats… (food)","answer":"grass and dates"}]},{"id":"RW-L01-U4-LS5-WR","type":"writing","instructions":"Writing: Make a fact page about your favorite animal: a title, a picture with labels and 4 fact sentences. Make a fact page about your favorite animal: a title, a picture with labels and 4 fact sentences.","instructions_ar":"اصنع صفحة حقائق عن حيوانك المفضل: عنوان، وصورة عليها بطاقات، و4 جمل حقائق.","prompt":"Make a fact page about your favorite animal: a title, a picture with labels and 4 fact sentences.","checklist":["My page has a title.","My picture has labels.","I wrote It is, It has, It can and It eats sentences.","After can, I used the plain word (can run).","I wrote It eats with -s.","Describing words come before naming words.","Every sentence has a capital letter and a period."],"rubric_id":"RW-RUBRIC-5T","min_words":16,"max_words":55,"organizer":"Animal Fact Plan (It is – It has – It can – It eats)","items":[{"q":"Make a fact page about your favorite animal: a title, a picture with labels and 4 fact sentences.","answer":"The Camel. It is big and brown. It has a long neck and a hump. It can walk in the hot desert. It eats grass and dates.","_w":{"checklist":["My page has a title.","My picture has labels.","I wrote It is, It has, It can and It eats sentences.","After can, I used the plain word (can run).","I wrote It eats with -s.","Describing words come before naming words.","Every sentence has a capital letter and a period."],"min":16,"max":55}}]}],"game":{"name":"Animal Fact Bingo","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Fact bingo: the app reads a fact (\"It has a hump.\"); the child taps the matching animal on a 3×3 board. Three in a row = bingo with a cheer.","Each student gets a bingo card and counters.","The caller reads a fact: \"It can swim and fly.\"","Students put a counter on the matching animal (duck).","Three in a row (across, down or corner to corner) = \"Bingo!\"","The winner reads back the facts to check; then the winner becomes the caller."],"data":[]},"exit_quiz":[{"q":"What does a fact page give you?","answer":"true information about an animal","explanation":"Fact pages give facts.","explanation_ar":"صفحة الحقائق تعطي معلومات صحيحة.","options":["a made-up story","a list of names","a poem with rhymes","true information about an animal"],"dok":1,"skill":"genre"},{"q":"Which sentence tells what an animal eats?","answer":"It eats seeds.","explanation":"It eats = food.","explanation_ar":"It eats للطعام.","options":["It eats seeds.","It is small.","It can fly.","It has wings."],"dok":1,"skill":"sentence starters"},{"q":"Which part of the page names parts of the picture?","answer":"the labels","explanation":"Labels name parts.","explanation_ar":"البطاقات تسمي الأجزاء.","options":["the title","the period","the labels","the checklist"],"dok":1,"skill":"text features"},{"q":"Which word is a body part?","answer":"tail","explanation":"A tail is part of the body.","explanation_ar":"الذيل جزء من الجسم.","options":["tail","farm","grass","seeds"],"dok":1,"skill":"vocabulary"},{"q":"Which sentence about a horse is correct?","answer":"It can run fast.","explanation":"Can + plain word.","explanation_ar":"can + فعل.","options":["It can runs fast.","It can to run fast.","It run can fast.","It can run fast."],"dok":2,"skill":"can"},{"q":"Which sentence about a rabbit is correct?","answer":"It has long ears.","explanation":"Describing word before ears.","explanation_ar":"الصفة قبل ears.","options":["It has ears long.","It has long ears.","It is have long ears.","It long ears has."],"dok":2,"skill":"word order"},{"q":"Fix this: *It eat grass.*","answer":"It eats grass.","explanation":"It + eats.","explanation_ar":"It eats.","options":["It eating grass.","It is eat grass.","It eats grass.","It can eats grass."],"dok":2,"skill":"editing"},{"q":"Which is the best title for a page about camels?","answer":"The Desert Camel","explanation":"A title names the topic.","explanation_ar":"العنوان يذكر الموضوع.","options":["It can walk.","The Desert Camel","my page","Grass"],"dok":2,"skill":"title"},{"q":"Where does a goat live in the model sentences?","answer":"on a farm","explanation":"The goat lives on a farm.","explanation_ar":"في المزرعة.","options":["on a farm","in the sea","in the sky","in a classroom"],"dok":1,"skill":"key details"},{"q":"Which fact page is the most complete?","answer":"a title, a labelled picture and It is/has/can/eats sentences","explanation":"It has all the parts.","explanation_ar":"فيها كل الأجزاء.","options":["only a picture","only a title","one sentence and no picture","a title, a labelled picture and It is/has/can/eats sentences"],"dok":3,"skill":"evaluate"}],"images":[{"id":"IMG-RW-L01-U4-LS5-V01","prompt":"Picture for the word 'tail': a cat with its tail curled"},{"id":"IMG-RW-L01-U4-LS5-V02","prompt":"Picture for the word 'ears': a rabbit's long ears"},{"id":"IMG-RW-L01-U4-LS5-V03","prompt":"Picture for the word 'neck': a camel's long curved neck"},{"id":"IMG-RW-L01-U4-LS5-V04","prompt":"Picture for the word 'food': a bowl of animal food"},{"id":"IMG-RW-L01-U4-LS5-V05","prompt":"Picture for the word 'grass': green grass with a horse grazing"},{"id":"IMG-RW-L01-U4-LS5-V06","prompt":"Picture for the word 'seeds': a small bird pecking at seeds"},{"id":"IMG-RW-L01-U4-LS5-V07","prompt":"Picture for the word 'farm': a small farm with a barn, palm trees and goats"},{"id":"IMG-RW-L01-U4-LS5-01","prompt":"A classroom wall with animal fact pages."},{"id":"IMG-RW-L01-U4-LS5-02","prompt":"A fact page about a horse with labels."},{"id":"IMG-RW-L01-U4-LS5-03","prompt":"A plan with a drawing space and four boxes."}],"audio":[{"id":"AUD-RW-L01-U4-LS5-V01","script":"tail. The cat has a long tail."},{"id":"AUD-RW-L01-U4-LS5-V02","script":"ears. A rabbit has long ears."},{"id":"AUD-RW-L01-U4-LS5-V03","script":"neck. A camel has a long neck."},{"id":"AUD-RW-L01-U4-LS5-V04","script":"food. Grass is food for goats."},{"id":"AUD-RW-L01-U4-LS5-V05","script":"grass. The horse eats grass."},{"id":"AUD-RW-L01-U4-LS5-V06","script":"seeds. Birds eat seeds."},{"id":"AUD-RW-L01-U4-LS5-V07","script":"farm. We see goats on the farm."},{"id":"AUD-RW-L01-U4-LS5-VID","script":"Omar loves horses. He makes a fact page! Plan: draw the horse. Add labels: tail, legs, ears. Draft: It is big and fast. It has a long tail. It can run very fast. It eats grass. Revise: It has a tail… It has a long, beautiful tail! Edit: It eats – add s! It can run – no s! Capitals and periods – check! Publish: put your page on the Animal Wall. Tell a friend one fact!"}]}],"unit_test":[{"q":"This farm animal says *quack* and swims on a pond.","answer":"duck","explanation":"Ducks quack and swim.","explanation_ar":"البطة.","options":["goat","duck","horse","camel"],"dok":1,"skill":"vocabulary","_part":"Part A – Words"},{"q":"A bird uses its ___ to fly.","answer":"wings","explanation":"Wings are for flying.","explanation_ar":"الأجنحة للطيران.","options":["ears","tail","legs","wings"],"dok":1,"skill":"vocabulary","_part":"Part A – Words"},{"q":"The kangaroo can ___ very high.","answer":"jump","explanation":"Kangaroos jump.","explanation_ar":"الكنغر يقفز.","options":["swim","jump","fly","read"],"dok":1,"skill":"movement words","_part":"Part A – Words"},{"q":"A turtle is not fast. It is ___.","answer":"slow","explanation":"Not fast = slow.","explanation_ar":"ليس سريعًا = بطيء.","options":["tiny","soft","slow","fast"],"dok":1,"skill":"opposites","_part":"Part A – Words"},{"q":"Goats and horses eat green ___.","answer":"grass","explanation":"They eat grass.","explanation_ar":"يأكلان العشب.","options":["grass","rocks","fish","wings"],"dok":1,"skill":"vocabulary","_part":"Part A – Words"},{"q":"An ant is very, very small. It is ___.","answer":"tiny","explanation":"Tiny = very small.","explanation_ar":"النملة صغيرة جدًا.","options":["big","beautiful","slow","tiny"],"dok":1,"skill":"vocabulary","_part":"Part A – Words"},{"q":"A fish and a camel are not the same. They are ___.","answer":"different","explanation":"Not the same = different.","explanation_ar":"مختلفان.","options":["tiny","soft","different","fast"],"dok":2,"skill":"vocabulary in context","_part":"Part A – Words"},{"q":"The kitten has ___ fur. It is nice to touch.","answer":"soft","explanation":"Nice to touch = soft.","explanation_ar":"ناعم.","options":["soft","slow","fast","tiny"],"dok":2,"skill":"vocabulary in context","_part":"Part A – Words"},{"q":"Which phrase about a horse is in the right order?","answer":"a fast horse","explanation":"Describing word before naming word.","explanation_ar":"الصفة قبل الاسم.","options":["a horse fast","a fast horse","horse fast a","fast a horse"],"dok":1,"skill":"word order","_part":"Part D – Check the sentences"},{"q":"Which sentence about a fish is correct?","answer":"A fish can swim.","explanation":"Can + plain word.","explanation_ar":"can + فعل.","options":["A fish can swims.","A fish can to swim.","A fish can swim.","A fish swim can."],"dok":1,"skill":"can","_part":"Part D – Check the sentences"},{"q":"Which sentence has a mistake?","answer":"It eat seeds.","explanation":"It + eats.","explanation_ar":"الصحيح It eats.","options":["It eats seeds.","It has wings.","It can fly.","It eat seeds."],"dok":2,"skill":"editing","_part":"Part D – Check the sentences"},{"q":"Which sentence about a camel is made up?","answer":"A camel can read books.","explanation":"Camels cannot read.","explanation_ar":"الجمل لا يقرأ.","options":["A camel has a hump.","A camel can read books.","A camel can walk on sand.","A camel eats grass."],"dok":2,"skill":"fact vs. made up","_part":"Part D – Check the sentences"},{"q":"Which starter tells what an animal looks like?","answer":"It is…","explanation":"It is + size/color.","explanation_ar":"It is للمظهر.","options":["It is…","It eats…","It can…","Last,…"],"dok":2,"skill":"sentence starters","_part":"Part D – Check the sentences"}],"unit_writing":{"task":"Write 4 fact sentences about an animal. Use It is…, It has…, It can… and It eats….","model":"The rabbit is small and white. It has long ears and soft fur. It can jump very high. It eats carrots and grass.","marks":20}});
